/* ⛔ GENERATED by kit/build.mjs from i18n/vi.json, the changelog and the kit. Do not edit. */
(window.FREALLY_I18N = window.FREALLY_I18N || {})["vi"] = {"hero.badge":"Phiên bản 1.5.0 là phiên bản hiện tại","hero.headline":"<span class=\"hl-muted\">Tự tin trước ống kính.</span> <span class=\"hl-bright\">Bám sát kịch bản.</span>","hero.sub":"Một máy nhắc chữ cho máy tính của bạn, đọc theo nhịp thật của con người — số ký tự mỗi giây, hoặc BPM của bản nhạc — và đánh dấu mọi khoảng dừng bạn viết vào kịch bản.","hero.chipDesktop":"Ứng dụng máy tính","hero.chipLanguages":"18 ngôn ngữ","hero.chipNoAccount":"Không cần tài khoản","what.is.title":"Đây là gì","what.is.lead":"Đọc kịch bản trước máy quay thường có nghĩa là cuộn quá nhanh hoặc quá chậm, một chỗ dừng bị quên, và màn hình thứ hai chậm hơn một dòng.","what.is.body":"Freally Teleprompt là máy nhắc chữ cho máy tính của bạn. Mở kịch bản được gửi cho bạn, đặt nhịp theo số ký tự mỗi giây hoặc theo BPM của bản nhạc, và nó chạy ở tốc độ đọc thật của con người — mọi chỗ dừng bạn viết đều được đánh dấu trong kịch bản, và mọi màn hình ở cùng một chữ.","what.title":"Ứng dụng làm gì","features.pace.title":"Nhịp đọc thật","features.pace.body":"Đặt tốc độ bằng số ký tự mỗi giây, hoặc bằng BPM từ 20 đến 250 để đọc khớp nhịp bản nhạc — không phải một núm xoay tùy tiện từ 1 đến 10.","features.pauses.title":"Khoảng dừng nhìn thấy được","features.pauses.body":"Gõ -- cho một khoảng dừng ngắn hoặc --3 để dừng ba giây. Mỗi khoảng dừng thành một chip trong trình soạn thảo, và sáng lên khi lượt đọc chạm tới.","features.screens.title":"Mọi màn hình ở cùng một từ","features.screens.body":"Một bộ máy duy nhất, tính bằng ký tự, điều khiển bản xem trước của bạn, máy chiếu của người dẫn — lật gương cho kính nhắc chữ nếu cần — và các điện thoại trong mạng của bạn, nên chúng không bao giờ lệch nhau.","features.import.title":"Mở tệp người ta gửi cho bạn","features.import.body":"Nhập tệp Word, RTF, PDF, văn bản thuần và Markdown thành văn bản nhắc chữ sạch, kèm báo cáo về mọi thứ không thể mang sang.","features.markers.title":"Định hướng trong kịch bản","features.markers.body":"Một dòng bắt đầu bằng # trở thành dấu mốc phần trong danh sách nhảy, bên cạnh tìm và thay thế và bộ đếm từ trực tiếp.","features.timing.title":"Đọc đúng giờ","features.timing.body":"Gõ nhịp độ của riêng bạn, nghe tiếng gõ có đếm vào, xem ô nhịp và phách, và tập dượt để có báo cáo thời gian theo từng phần.","features.control.title":"Bàn đạp, bút trình chiếu và phím nóng","features.control.body":"Mỗi lệnh có một phím bạn có thể đổi. Bàn đạp chân và bút trình chiếu được gán như mọi phím khác, và một phím có thể hoạt động ngay cả khi ứng dụng không ở phía trước.","features.writing.title":"Hỗ trợ khi bạn viết","features.writing.body":"Tự động hoàn thành bằng 18 ngôn ngữ từ danh sách từ có sẵn trong ứng dụng, và đọc chính tả tiếng Anh: bạn nói, chữ được viết vào kịch bản.","features.private.title":"Của bạn, trên máy của bạn","features.private.body":"Không tài khoản, không đo lường từ xa, không đám mây. Kịch bản là các tệp đơn giản trên máy tính của bạn, và ứng dụng chỉ hỏi internet một điều: có phiên bản mới hơn không.","ladder.title":"Con đường đến 2.0","ladder.intro":"Mọi bản phát hành đến nay, rồi các bước đã lên kế hoạch trên đường đến 2.0. Một bước chỉ có số phiên bản khi được phát hành, và kế hoạch có thể thay đổi.","ladder.rung.v0.100.0":"Nền móng: ứng dụng chạy trên Windows, macOS và Linux, đề nghị bạn chấp nhận giấy phép, và cuộn kịch bản bằng bộ máy dựa trên ký tự từ Freally Capture.","ladder.rung.v0.200.0":"Máy nhắc chữ độc lập: thư viện kịch bản, chip khoảng dừng, máy chiếu cho người dẫn có lật gương, phản chiếu tới điện thoại trong mạng của bạn, điều khiển phát thật sự, nhịp theo BPM và đọc to.","ladder.rung.v0.300.0":"Tự động hoàn thành ngoại tuyến: hoàn tất từ và cụm từ thông dụng khi bạn gõ, bằng cả 18 ngôn ngữ, từ các danh sách từ có sẵn trong ứng dụng.","ladder.rung.v1.0.0":"Bản phát hành đầy đủ đầu tiên: phần giới thiệu một phút, đợt hoàn thiện cho bàn phím và trình đọc màn hình, giao diện theo hệ thống, và bản cập nhật chỉ cài khi bạn đồng ý.","ladder.rung.v1.1.0":"Viết kịch bản bằng giọng nói: đọc chính tả chạy ngay trên máy tính của bạn, không cần huấn luyện gì.","ladder.rung.v1.2.0":"Đọc chính tả, hoàn thiện: nút ghi đúng nghĩa, chữ xuất hiện ở chỗ con trỏ, và lệnh hoàn tác chỉ rút lại một điều bạn vừa nói.","ladder.rung.v1.3.0":"Đọc đúng giờ: nhịp độ bạn gõ để khớp với cách nói của mình, máy đếm nhịp, bộ đếm ô nhịp và phách, tập dượt kèm báo cáo thời gian, và nhãn không tốn thời gian đọc.","ladder.rung.v1.4.0":"Đưa kịch bản vào: nhập tệp Word, RTF, PDF, văn bản và Markdown, dấu mốc phần với danh sách nhảy, tìm và thay thế, và thống kê kịch bản.","ladder.rung.v1.5.0":"Mọi thứ trong phòng đều điều khiển được: bàn đạp chân và bút trình chiếu, phím vẫn hoạt động khi ứng dụng không ở phía trước, và bản đồ có thể gán lại cho mọi lệnh.","ladder.rung.rig":"Dành cho bộ khung máy: lật dọc cho kính phía trên ống kính, đường dẫn ống kính và lề an toàn, màn hiển thị thời gian đã qua và còn lại, và cài đặt sẵn để đọc từ xa.","ladder.rung.takes":"Không bao giờ mất cảnh quay: khôi phục chỉnh sửa chưa lưu sau sự cố, cài đặt đi theo từng kịch bản, lịch sử phiên bản cục bộ, và xuất ra PDF làm bản giấy dự phòng.","ladder.rung.writing":"Hỗ trợ viết: công cụ tìm vần, đếm âm tiết từng dòng, kiểm tra câu khó đọc và khoảng dừng gợi ý — từ từ điển, không dùng mô hình.","ladder.rung.remote":"Điều khiển từ bất cứ đâu: trang điều khiển cỡ điện thoại, cùng MIDI và OSC cho bàn điều khiển bạn đang dùng — chỉ trong mạng của bạn, và tắt theo mặc định.","ladder.rung.show":"Điều hành cả một chương trình: kịch bản chạy chương trình với thời lượng từng mục, nhiều hơn một đầu ra nhắc chữ, và màn đếm ngược lớn có đèn tín hiệu cho trường quay.","ladder.rung.record":"Ghi hình khi đọc: một cảnh quay webcam trong lúc kịch bản chạy, hoặc chỉ âm thanh với dấu mốc phần được ghi vào tệp dưới dạng chương.","ladder.rung.languages":"Mọi kịch bản, mọi ngôn ngữ: nhấn mạnh từng từ, furigana phía trên dòng, chỉnh chu cho tiếng Ả Rập viết từ phải sang trái, và tiếng Nhật, tiếng Trung viết dọc.","ladder.rung.v2.0.0":"Phiên bản 2.0: tất cả những điều trên, trên Windows, macOS và Linux.","ladder.note":"Xong nghĩa là đã phát hành và gắn thẻ. Dù vậy, trang này không cung cấp bản tải xuống.","honest.title":"Những điều mà hầu hết các trang web đặt ở cuối trang","honest.model.title":"Đọc chính tả dùng một mô hình giọng nói","honest.model.body":"Đọc chính tả là phần duy nhất của ứng dụng dùng học máy: Vosk, một bộ nhận dạng giọng nói mã nguồn mở, với một mô hình tiếng Anh nhỏ khoảng 40 MB nằm sẵn trong ứng dụng. Nó chạy trên máy tính của bạn, không tải lên hay tải xuống gì, chỉ hiểu tiếng Anh, và tắt cho đến khi bạn bật. Mọi thứ khác là mã thông thường và danh sách từ.","honest.update.title":"Ứng dụng hỏi internet đúng một câu","honest.update.body":"Mỗi lần khởi động, ứng dụng hỏi GitHub xem có phiên bản mới hơn không. Yêu cầu này không mang kịch bản, cài đặt hay mã định danh nào, và không gì được cài nếu bạn không đồng ý. Mọi thứ khác hoạt động mà không cần kết nối nào.","honest.voice.title":"Ứng dụng không đi theo giọng bạn","honest.voice.body":"Một số máy nhắc chữ cuộn bằng cách nghe bạn đọc. Freally Teleprompt 1.5.0 cuộn theo nhịp bạn đặt, và chính bạn, một phím hay một bàn đạp sẽ tiếp quản khi lượt đọc thay đổi. Một chế độ đi theo giọng nói đã được thử ở 1.0.0 và bị gỡ bỏ ở 1.1.0.","honest.downloads.title":"Trang này không có bản tải xuống","honest.downloads.body":"Không có liên kết tải xuống, không có nút, không có bản beta. Mã nguồn cũng là riêng tư.","site.tagline":"Tự tin trước ống kính. Bám sát kịch bản.","footer.licence":"Phần mềm độc quyền — Bảo lưu mọi quyền. © Mike Weaver. Hiện miễn phí sử dụng; các phiên bản sau này có thể được bán. Không phải mã nguồn mở.","footer.yours":"Kịch bản của bạn là của bạn. Chúng ở lại trên máy tính của bạn, và tác giả ứng dụng không bao giờ nhận, lưu hay chuyển tiếp chúng.","featuresPage.lead":"Một máy nhắc chữ cho Windows, macOS và Linux, đọc theo nhịp thật của con người, giữ mọi màn hình ở cùng một từ, và mở kịch bản người ta gửi cho bạn.","featuresPage.version":"Trang này mô tả Freally Teleprompt 1.5.0, phiên bản đã phát hành: mọi thứ trên trang đều có trong 1.5.0, và không có gì đang còn trong kế hoạch.","featuresPage.numbers.intro":"Mỗi con số là điều phiên bản 1.5.0 làm được, đếm từ mã nguồn của nó. Không con số nào được làm tròn lên.","featuresPage.numbers.paces":"cách đặt nhịp: số ký tự mỗi giây hoặc BPM","featuresPage.numbers.bpm":"BPM: khoảng nhịp ứng dụng đọc theo phách","featuresPage.numbers.formats":"loại tệp có thể nhập: Word, RTF, PDF, văn bản thuần và Markdown","featuresPage.numbers.systems":"hệ điều hành: Windows, macOS và Linux","featuresPage.numbers.languages":"ngôn ngữ, trong ứng dụng và trong tự động hoàn thành","featuresPage.numbers.words":"từ trong danh sách tự động hoàn thành, cùng 344.891 cụm từ","featuresPage.numbers.accounts":"tài khoản cần tạo","featuresPage.numbers.model":"mô hình giọng nói, cho đọc chính tả: trên máy của bạn, và tắt cho đến khi bạn bật","featuresPage.numbers.price":"giá hiện nay","featuresPage.free.title":"Hiện miễn phí","featuresPage.free.body":"Mọi thứ Freally Teleprompt 1.5.0 làm được hiện miễn phí cho tất cả mọi người: không có gói trả phí, không thuê bao, không tài khoản và không có bản dùng thử hết hạn.","featuresPage.cards.title":"Phiên bản 1.5.0 làm gì","featuresPage.cards.pace.title":"Nhịp đọc thật","featuresPage.cards.pace.body":"Số ký tự mỗi giây, hoặc BPM từ 20 đến 250 cho lời bài hát và đoạn thơ đọc theo bản nhạc. Đổi một trong hai khi kịch bản đang chạy và tốc độ cuộn điều chỉnh ngay.","featuresPage.cards.pauses.title":"Chip khoảng dừng","featuresPage.cards.pauses.body":"Gõ -- cho một khoảng dừng ngắn hoặc --N để dừng N giây. Mỗi khoảng dừng là một chip con trỏ không tách được, sáng lên khi lượt đọc chạm tới, và chế độ đọc to biến nó thành một khoảng lặng thật.","featuresPage.cards.engine.title":"Mọi màn hình ở cùng một từ","featuresPage.cards.engine.body":"Bản xem trước, máy chiếu và các thiết bị trong mạng của bạn theo cùng một bộ máy tính bằng ký tự, nên chúng thống nhất về từ đang được đọc ngay cả khi cỡ chữ khác nhau.","featuresPage.cards.projector.title":"Máy chiếu cho người dẫn","featuresPage.cards.projector.body":"Toàn màn hình trên bất kỳ màn hình nào, lật gương cho kính bán phản xạ, với điều khiển phát và phím riêng cho người đang đọc.","featuresPage.cards.mirror.title":"Phản chiếu tới điện thoại và máy tính bảng","featuresPage.cards.mirror.body":"Tắt cho đến khi bạn bật. Một liên kết và mã QR mở kịch bản trong bất kỳ trình duyệt nào trong mạng của bạn: chỉ đọc, với khóa thay đổi mỗi lần ứng dụng khởi động.","featuresPage.cards.import.title":"Nhập Word, RTF, PDF, văn bản và Markdown","featuresPage.cards.import.body":"Văn bản nhắc chữ sạch, giữ nguyên các đoạn, kèm báo cáo đếm những gì không mang sang được — hình ảnh, chú thích cuối trang, bình luận. Không gì được lưu cho đến khi bạn đồng ý.","featuresPage.cards.markers.title":"Dấu mốc phần, tìm và thay thế","featuresPage.cards.markers.body":"Một dòng bắt đầu bằng # là một dấu mốc trên thanh tiến trình và trong danh sách nhảy. Tìm và thay thế phân biệt hoa thường hoặc nguyên từ, và hoàn tác chỉ bằng một lần nhấn.","featuresPage.cards.timing.title":"Nhịp độ, tiếng gõ và ô nhịp","featuresPage.cards.timing.body":"Gõ nhịp độ để BPM khớp với cách nói của bạn, nghe tiếng gõ có đếm vào, và xem ô nhịp và phách trên màn hình và dưới dạng vạch trên thanh tiến trình.","featuresPage.cards.rehearsal.title":"Tập dượt và báo cáo thời gian","featuresPage.cards.rehearsal.body":"Đọc hết một lượt và xem thời gian dự kiến của từng phần cạnh thời gian thực, cùng nhịp bạn thực sự đã đọc. Chỉ ghi lại thời gian — không micrô, không âm thanh.","featuresPage.cards.skip.title":"Nhãn không tốn thời gian","featuresPage.cards.skip.body":"Đánh dấu Chorus, [Verse 1] hay ## Bridge là những từ bạn không trình diễn: chúng vẫn ở trên màn hình, mờ đi, và không tốn thời gian đọc, nên lời bài hát vẫn đúng ô nhịp.","featuresPage.cards.control.title":"Phím tắt, bàn đạp và phím nóng","featuresPage.cards.control.body":"Bản đồ có thể tìm kiếm của mọi lệnh, có đánh dấu xung đột. Bàn đạp và bút trình chiếu được gán như mọi phím, và một phím có thể hoạt động khi ứng dụng khác đang ở phía trước.","featuresPage.cards.writing.title":"Tự động hoàn thành, đọc chính tả và đọc to","featuresPage.cards.writing.body":"Gợi ý từ và cụm từ bằng 18 ngôn ngữ từ danh sách có sẵn trong ứng dụng, đọc chính tả tiếng Anh chạy trên máy của bạn, và đọc to bằng chính giọng của hệ thống.","featuresPage.cards.look.title":"Diện mạo của bạn, ngôn ngữ của bạn","featuresPage.cards.look.body":"Phông chữ, cỡ, độ đậm, màu, lề, giãn dòng và dòng đọc, áp dụng cùng lúc cho mọi màn hình. Ứng dụng có 18 ngôn ngữ, với giao diện tối hoặc sáng.","featuresPage.cards.private.title":"Không tài khoản, không đám mây","featuresPage.cards.private.body":"Kịch bản là các tệp đơn giản trên máy tính của bạn, và không có đo lường từ xa. Yêu cầu duy nhất của ứng dụng tới internet là kiểm tra phiên bản mới hơn, và không gì được cài khi bạn chưa đồng ý.","featuresPage.compare.title":"Đặt cạnh các máy nhắc chữ thương mại","featuresPage.compare.intro":"Freally Teleprompt 1.5.0 — phiên bản đã phát hành, bản bạn dùng được hôm nay — đặt cạnh sáu ứng dụng nhắc chữ thương mại. Mỗi ô của sản phẩm khác đều lấy từ trang của chính nhà sản xuất hoặc trang của họ trên cửa hàng ứng dụng, được kiểm tra ngày 2 tháng 10 năm 2026, và giá tính bằng đô la Mỹ tại thời điểm tháng 10 năm 2026.","featuresPage.compare.feature":"Tính năng","featuresPage.compare.row.price":"Giá (USD, tháng 10 năm 2026)","featuresPage.compare.freeToday":"Hiện miễn phí","featuresPage.compare.unit.perMonth":"mỗi tháng","featuresPage.compare.unit.perYear":"mỗi năm","featuresPage.compare.unit.once":"trả một lần","featuresPage.compare.unit.onSale":"đang giảm giá; thường là $99","featuresPage.compare.row.systems":"Ứng dụng máy tính cho Windows, macOS và Linux","featuresPage.compare.legend.yes":"có","featuresPage.compare.legend.partly":"một phần","featuresPage.compare.note.browser":"và trong trình duyệt web","featuresPage.compare.row.noAccount":"Dùng được mà không cần tạo tài khoản","featuresPage.compare.legend.no":"không","featuresPage.compare.legend.unknown":"chưa xác minh","featuresPage.compare.row.offline":"Hoạt động không cần kết nối internet","featuresPage.compare.note.updateCheck":"chỉ việc kiểm tra cập nhật kết nối mạng","featuresPage.compare.note.afterRegistration":"sau khi đăng ký trực tuyến","featuresPage.compare.row.import":"Mở tệp Word và PDF","featuresPage.compare.note.ourFormats":"cả RTF, văn bản thuần và Markdown","featuresPage.compare.note.wordIos":"Word chỉ trên iPhone và iPad","featuresPage.compare.note.textRtf":"chỉ văn bản thuần và RTF","featuresPage.compare.row.bpm":"Cuộn theo nhịp độ âm nhạc (BPM)","featuresPage.compare.row.pauses":"Khoảng dừng có thời lượng viết trong kịch bản","featuresPage.compare.row.mirror":"Chữ lật gương cho kính nhắc chữ","featuresPage.compare.row.devices":"Hiển thị kịch bản trên thiết bị khác","featuresPage.compare.note.ownNetwork":"trong mạng của bạn, qua trình duyệt","featuresPage.compare.note.portal":"qua cổng của nhà sản xuất, trực tuyến","featuresPage.compare.note.internet":"qua internet","featuresPage.compare.note.btWifi":"qua Bluetooth, Wi-Fi hoặc internet","featuresPage.compare.note.displayOrLan":"màn hình thứ hai, hoặc thiết bị khác trong mạng","featuresPage.compare.note.secondMonitor":"màn hình thứ hai; máy tính bảng cần ứng dụng khác","featuresPage.compare.row.remotes":"Bàn đạp chân và bút trình chiếu","featuresPage.compare.note.keyboardOnly":"chỉ phím tắt bàn phím","featuresPage.compare.row.voiceScroll":"Cuộn theo giọng nói của bạn","featuresPage.compare.note.removed":"đã gỡ ở 1.1.0","featuresPage.compare.note.paidAddon":"một tiện ích trả phí","featuresPage.compare.summaryTitle":"Tóm lại","featuresPage.compare.summary":"Tóm lại: trong bảy ứng dụng này, chỉ Freally Teleprompt nói rằng nó cuộn theo BPM và giữ các khoảng dừng có thời lượng viết trong kịch bản, và là ứng dụng duy nhất chạy trên Windows, macOS và Linux mà không cần tài khoản lẫn trả tiền.","featuresPage.compare.theyWinTitle":"Họ hơn ở đâu","featuresPage.compare.theyWin":"Chỗ họ hơn: PromptSmart, Speakflow và Teleprompter.com cuộn theo giọng bạn, và TeleScroll cũng làm được với một tiện ích trả phí; Freally Teleprompt 1.5.0 thì không. PromptSmart, Teleprompter.com và Teleprompter Pro có ứng dụng điện thoại và máy tính bảng quay video trong lúc bạn đọc và lưu kịch bản của bạn trên đám mây của họ, còn Speakflow có thêm công cụ viết bằng AI và cộng tác theo thời gian thực.","featuresPage.compare.asOf":"Cột của Freally Teleprompt là phiên bản 1.5.0, đã được phát hành, nên bảng so sánh những gì bạn dùng được hôm nay. Giá là giá hôm nay: Freally Teleprompt hiện miễn phí, và các phiên bản sau có thể được bán. Các sản phẩm khác cũng thay đổi; bảng này đúng tại ngày 2 tháng 10 năm 2026.","featuresPage.why.title":"Vì sao nó được làm như vậy","featuresPage.why.engine.title":"Một bộ máy, tính bằng ký tự","featuresPage.why.engine.body":"Tốc độ là số ký tự mỗi giây, nên bản xem trước, máy chiếu và mọi điện thoại đi qua cùng một văn bản với cùng tốc độ, bất kể cỡ chữ. Bộ máy được viết hai lần, cho lõi của ứng dụng và cho giao diện, và hai bản được giữ giống hệt nhau.","featuresPage.why.import.title":"Bộ chuyển đổi nói rõ những gì đã bỏ","featuresPage.why.import.body":"Một lần nhập sẽ đếm những gì không mang sang được thay vì lặng lẽ làm mất, và không bao giờ biến một dấu gạch ngang in ấn thành khoảng dừng mà không ai viết.","featuresPage.why.isolate.title":"Một tệp hỏng không thể làm dừng lượt đọc","featuresPage.why.isolate.body":"Tài liệu được đọc trong một tiến trình riêng có giới hạn thời gian, nên một tệp PDF hỏng chỉ chấm dứt lần nhập đó, không phải máy nhắc chữ.","featuresPage.why.local.title":"Mọi thứ ở lại trên máy của bạn","featuresPage.why.local.body":"Không tài khoản, không đo lường từ xa và không đám mây. Kịch bản của bạn là các tệp văn bản thuần mở được bằng mọi trình soạn thảo, và bản phản chiếu qua mạng chỉ ở trong mạng của bạn.","featuresPage.why.consent.title":"Không có gì diễn ra sau lưng bạn","featuresPage.why.consent.body":"Cài đặt chỉ thay đổi khi bạn nhấn Áp dụng, một phím chỉ được giữ toàn hệ thống khi bạn yêu cầu, và bản cập nhật chỉ được cài sau khi bạn đồng ý.","featuresPage.why.keyboard.title":"Trong tầm bàn phím","featuresPage.why.keyboard.body":"Mọi điều khiển đều có vòng tiêu điểm, hộp thoại giữ tiêu điểm bên trong, thanh tiến trình là một thanh trượt thật, và các tùy chọn giảm chuyển động và giảm độ trong suốt đều được tôn trọng.","featuresPage.coming.title":"Những gì vẫn đang đến","featuresPage.coming.intro":"Nói thẳng, vì một danh sách tính năng che giấu chỗ thiếu thì không đáng đọc. Mọi thứ trên trang này đều có trong 1.5.0; các bước tiếp theo nằm trên con đường đến 2.0, mỗi bước kèm trạng thái của nó.","featuresPage.limits.title":"Những gì 1.5.0 không làm","featuresPage.limits.voice":"Ứng dụng không cuộn theo giọng bạn: bạn đặt nhịp, và một phím hay một bàn đạp sẽ tiếp quản khi lượt đọc thay đổi.","featuresPage.limits.dictation":"Đọc chính tả chỉ hiểu tiếng Anh; tự động hoàn thành và giao diện có đủ cả 18 ngôn ngữ.","featuresPage.limits.phone":"Không có ứng dụng điện thoại hay máy tính bảng: điện thoại có thể hiển thị kịch bản qua bản phản chiếu mạng, chỉ đọc, nhưng không điều khiển được.","featuresPage.limits.recording":"Ứng dụng không quay video hay ghi âm trong lúc bạn đọc.","featuresPage.limits.wayland":"Trên Linux với Wayland, một phím được đặt để hoạt động khi ứng dụng khác ở phía trước có thể không hoạt động, vì Wayland không cho ứng dụng giữ phím toàn hệ thống; các phím bên trong ứng dụng không bị ảnh hưởng.","featuresPage.coming.downloads":"Trang web này không có bản tải xuống, và trang này cũng vậy.","docs.intro":"Cách dùng Freally Teleprompt, từ lần khởi động đầu tiên đến một lượt đọc trên bộ khung máy.","docs.start.title":"Bắt đầu","docs.write.title":"Viết kịch bản","docs.import.title":"Nhập tài liệu","docs.find.title":"Tìm và thay thế","docs.markers.title":"Dấu mốc phần","docs.pauses.title":"Chip khoảng dừng","docs.pacing.title":"Nhịp: số ký tự mỗi giây hoặc BPM","docs.tempo.title":"Nhịp độ, ô nhịp và tiếng gõ","docs.rehearsal.title":"Tập dượt và báo cáo thời gian","docs.skip.title":"Những từ bạn không trình diễn","docs.playback.title":"Phát và điều khiển","docs.shortcuts.title":"Phím tắt, bàn đạp và phím nóng","docs.countdown.title":"Đếm ngược trước khi bắt đầu","docs.projector.title":"Máy chiếu","docs.mirror.title":"Phản chiếu qua mạng","docs.readAloud.title":"Đọc to","docs.autocomplete.title":"Tự động hoàn thành","docs.dictation.title":"Đọc chính tả","docs.settings.title":"Giao diện, ngôn ngữ và cài đặt","docs.access.title":"Phần giới thiệu và trợ năng","docs.problems.title":"Sự cố và cập nhật","docs.privacy.title":"Quyền riêng tư và mạng","docs.start.p1":"Freally Teleprompt là máy nhắc chữ cho Windows, macOS và Linux, dành cho người dẫn, streamer, podcaster, diễn viên, ca sĩ và rapper. Ứng dụng mở trong một cửa sổ duy nhất — kịch bản, trình soạn thảo, bản xem trước và điều khiển máy chiếu — và không cần tài khoản.","docs.start.p2":"Lần đầu mở, ứng dụng hiển thị thỏa thuận giấy phép. Cuộn đến cuối, rồi chọn Tôi Đồng ý hoặc Từ chối & Thoát. Không thể dùng ứng dụng cho đến khi bạn đồng ý; câu trả lời được ghi nhớ, và bạn chỉ được hỏi lại nếu thỏa thuận thay đổi.","docs.start.p3":"Sau đó, phần giới thiệu một phút cho thấy trình soạn thảo, điều khiển nhịp và máy chiếu. Gõ hoặc dán một kịch bản, đặt nhịp và nhấn phát.","docs.start.p4":"Trang này không có bản tải xuống, và mã nguồn là riêng tư.","docs.write.p1":"Kịch bản là các tệp .ftscript: văn bản thuần trong một thư mục, đọc được bằng mọi trình soạn thảo văn bản. Mở Kịch bản trên thanh công cụ để tạo, mở, đổi tên và xóa chúng. Danh sách gần đây đưa bạn trở lại việc đang làm, mọi thứ được lưu khi bạn gõ, và ứng dụng mở lại kịch bản bạn mở lần cuối.","docs.write.p2":"Gõ trong trình soạn thảo hoặc dán từ bất cứ đâu. Bên dưới ước tính thời gian đọc, bộ đếm từ và ký tự trực tiếp cho biết những gì bạn thực sự sẽ trình diễn — nhãn bị bỏ qua và dấu khoảng dừng không được tính — và một cảnh báo đánh dấu dòng nào dài đến mức là cả một đoạn văn.","docs.import.p1":"Nhấn Nhập trên thanh công cụ và chọn một tài liệu Word (.docx), một tệp RTF, một tệp PDF, một tệp văn bản thuần hoặc một tệp Markdown. Bạn sẽ thấy văn bản thu được, cùng một báo cáo, trước khi bất cứ thứ gì được lưu.","docs.import.p2":"Các đoạn văn được giữ; chữ đậm, phông chữ và màu sắc bị làm phẳng, vì máy nhắc chữ chỉ hiển thị một phông. Dấu ngoặc kép cong, gạch ngang dài và dấu ba chấm thành ký tự thường, và tệp được lưu bằng bảng mã cũ được đọc đúng, kèm báo cáo cho biết điều đó.","docs.import.p3":"Hình ảnh, chú thích cuối trang, bình luận, đầu trang và chân trang, địa chỉ liên kết và đối tượng nhúng đều được đếm và liệt kê, không bao giờ bị bỏ đi lặng lẽ. Tệp PDF không có cấu trúc như vậy, nên với PDF, báo cáo nói rằng không thể xác định.","docs.import.p4":"Đặt tên cho kịch bản — một cái tên được gợi ý từ tệp — rồi nhấn Nhập. Kịch bản được thêm vào thư viện và mở ra, và không bao giờ ghi đè một kịch bản đã có. Tiêu đề Markdown đến dưới dạng dòng #, nên một kịch bản Markdown có sẵn các dấu mốc phần.","docs.import.p5":"Dấu gạch ngang in ấn trở thành dấu gạch nối thường, và hai dấu liền nhau không bao giờ thành khoảng dừng, nên một vở kịch được nhập không đầy những khoảng dừng mà không ai viết. Tệp văn bản bạn viết với dấu khoảng dừng thật vẫn giữ chúng.","docs.find.p1":"Nhấn Ctrl+F, hoặc Tìm trên thanh công cụ, để tìm trong kịch bản đang mở. Số kết quả cập nhật khi bạn gõ; Enter đến kết quả tiếp theo và Shift+Enter đến kết quả trước, quay vòng ở cả hai đầu.","docs.find.p2":"Phân biệt hoa thường và Chỉ nguyên từ thu hẹp tìm kiếm, và những gì bạn gõ được tìm đúng nguyên văn. Thay thế đổi kết quả hiện tại và Thay tất cả đổi mọi kết quả; cả hai đều hoàn tác bằng một lần Ctrl+Z.","docs.markers.p1":"Bắt đầu một dòng bằng # — # Verse 2, # Q&A, ## Bridge — và nó trở thành dấu mốc phần. Mọi dòng là một trong những từ bỏ qua của bạn, như [Chorus], cũng là dấu mốc. Không có gì phải thiết lập.","docs.markers.p2":"Dấu mốc xuất hiện trong danh sách nhảy cạnh thanh tiến trình, cho biết bạn đang ở phần nào, và được vạch ngay trên thanh. Tiếp và Trước đi qua chúng; Trước trước hết đưa về đầu phần bạn đang ở, giống nút bài trước. Chọn một dấu mốc sẽ di chuyển mọi màn hình, kể cả máy chiếu.","docs.pauses.p1":"Gõ -- (một dấu cách, hai gạch nối, một dấu cách) cho khoảng dừng ngắn, hoặc --N để dừng N giây. Mỗi khoảng dừng thành một chip trong trình soạn thảo: con trỏ chỉ đứng trước hoặc sau nó, một lần Backspace xóa nó, và Shift với phím mũi tên chọn trọn nó. Đặt độ dài của một -- đơn thuần trong Cài đặt → Đọc.","docs.pauses.p2":"Sao chép và dán giữ nguyên chip, và văn bản dán vào được sắp lại khoảng trắng để mỗi khoảng dừng thành một chip gọn. Khi kịch bản chạy, mỗi khoảng dừng sáng lên khi lượt đọc chạm tới và việc cuộn dừng đúng độ dài của nó — như nhau trên bản xem trước, máy chiếu và bản phản chiếu qua mạng.","docs.pacing.p1":"Đặt tốc độ bằng số ký tự mỗi giây: một nhịp đọc thật mà mọi màn hình đều theo, bất kể cỡ chữ. Hoặc chuyển sang BPM, từ 20 đến 250, để đọc lời bài hát và đoạn thơ khớp nhịp bản nhạc.","docs.pacing.p2":"Cả hai điều khiển cùng một bộ máy, và đổi một trong hai khi kịch bản đang chạy sẽ điều chỉnh nhịp ngay lập tức.","docs.tempo.p1":"Nhịp độ trở thành tốc độ đọc qua một con số: bạn đọc bao nhiêu ký tự trong một phách. Trong Cài đặt → Định thời → Nhịp độ của riêng bạn, nhấn Gõ ba lần trở lên theo nhịp bạn biểu diễn, rồi chọn Dùng nhịp độ này; Trở về mặc định sẽ hoàn tác. Từ đó ô BPM chỉ đưa ra những nhịp độ mà bộ máy đạt được.","docs.tempo.p2":"Khi bật BPM, hoặc bật tiếng gõ, ô nhịp và phách hiện phía trên thanh tiến trình và vạch nhịp được kẻ lên thanh. Đặt số phách trong một ô nhịp, từ 2 đến 12, trong Cài đặt → Định thời.","docs.tempo.p3":"Đánh dấu Phát tiếng gõ theo nhịp độ hiện tại để nghe một tiếng tích nhẹ ở mỗi phách, cao hơn ở phách đầu của mỗi ô nhịp; đếm ngược trước khi bắt đầu trở thành phần đếm vào. Ứng dụng tự tạo âm thanh và căn từng tiếng tích theo đồng hồ âm thanh, nên không bị trôi. Nó im lặng khi chế độ đọc to đang nói.","docs.rehearsal.p1":"Đánh dấu Tập dượt và đo thời gian đọc của tôi bên dưới điều khiển phát, nhấn phát và đọc to như vào ngày quay. Tạm dừng, quay lại, đổi tốc độ: tất cả đều là một phần của phép đo.","docs.rehearsal.p2":"Bỏ đánh dấu và báo cáo tập dượt mở ra: mỗi phần một dòng, gồm thời gian lẽ ra cần ở nhịp của bạn, thời gian thực tế và chênh lệch. Các phần là các đoạn văn của bạn, hoặc các dấu mốc phần khi kịch bản được chia theo chúng. Nếu bạn đọc ở nhịp khác, báo cáo sẽ đề xuất tốc độ đó, và một cú nhấp sẽ áp dụng nó.","docs.rehearsal.p3":"Trong lúc tập dượt, một cảnh báo nhẹ xuất hiện khi lượt đọc chậm hơn hoặc nhanh hơn kế hoạch từ ba giây trở lên. Tập dượt chỉ ghi lại thời gian và không gì khác: nó không mở micrô, không giữ âm thanh, và không thể chạy cùng lúc với chế độ đọc to.","docs.skip.p1":"Nhãn phần — Chorus, Verse 2, Bridge — là những mốc bạn thấy trước nhưng không bao giờ đọc. Liệt kê chúng trong Cài đặt → Định thời → Những từ bạn không trình diễn, mỗi dòng một từ. Danh sách ban đầu để trống, vì nó thay đổi cách tính thời gian của kịch bản.","docs.skip.p2":"Một dòng chỉ gồm nhãn sẽ bị bỏ qua toàn bộ: ngoặc vuông, dấu thăng, dấu hai chấm và một con số ở cuối đều được bỏ qua, nên Chorus, [Verse 1], ## Bridge và Chorus: đều khớp. Cùng từ đó nằm trong một dòng thật chỉ bỏ qua chính nó. Việc so khớp bỏ qua chữ hoa và chỉ khớp nguyên từ.","docs.skip.p3":"Văn bản bị bỏ qua vẫn ở trên màn hình, mờ đi, để người dẫn vẫn thấy trước, và chế độ đọc to không bao giờ đọc nó. Vì nhãn không tốn thời gian, việc cuộn lướt qua ngay — và lời bài hát của bạn vẫn ở đúng ô nhịp bạn đã viết.","docs.playback.p1":"Phát, tạm dừng, dừng, tua lùi và tua tới là các nút trên màn hình; giữ tua lùi hoặc tua tới để tiếp tục. Lăn chuột để tua, nhấp vào một từ để bắt đầu từ đó, hoặc rê chuột trên thanh tiến trình để xem các từ tại điểm đó.","docs.playback.p2":"Thanh tiến trình hiển thị thời gian đọc đã qua và tổng thời gian, kể cả khoảng dừng. Một đường dẫn đọc giữ từ hiện tại trên dòng đọc, và từ vừa sáng cuối cùng không bao giờ cuộn khuất.","docs.shortcuts.p1":"Mở Phím tắt trên thanh công cụ. Nhấn vào phím gán bạn muốn đổi, rồi nhấn phím, bút trình chiếu hay bàn đạp bạn muốn; Escape giữ nguyên như cũ. Tìm theo tên lệnh hoặc theo chính phím đó. Nếu hai lệnh dùng chung một phím, cả hai dòng đều báo; xóa một phím gán bằng × hoặc chọn Khôi phục mặc định.","docs.shortcuts.p2":"Hầu hết bàn đạp chân và bút trình chiếu gửi các phím bình thường, thường là F13 đến F24, nên chúng được gán mà không cần trình điều khiển hay thiết lập. Phím gán theo phím vật lý, không theo chữ in trên phím, nên vẫn hoạt động khi đổi bố cục bàn phím.","docs.shortcuts.p3":"Cột Mọi nơi yêu cầu hệ thống chuyển phím cho ứng dụng ngay cả khi ứng dụng khác ở phía trước — ứng dụng camera, DAW hay OBS. Không gì bị giữ cho đến khi bạn đặt, và một phím đã thuộc về chương trình khác sẽ báo cho bạn. Trên Linux với Wayland, ứng dụng không thể giữ phím toàn hệ thống, và hộp thoại sẽ cho bạn biết.","docs.shortcuts.p4":"Trong lúc bạn viết, phím cách, các phím mũi tên và Home vẫn gõ bình thường: một phím đơn chỉ chạy lệnh của nó khi ở ngoài trình soạn thảo.","docs.countdown.p1":"Đặt Đếm ngược trước khi bắt đầu trong Cài đặt → Đọc, và khi nhấn phát, ứng dụng sẽ đếm ngược số giây đó trước, trên bản xem trước và máy chiếu, để người dẫn có một khoảnh khắc trước khi từ đầu tiên chuyển động. Khi bật tiếng gõ, phần đếm ngược cũng là phần đếm vào.","docs.projector.p1":"Nhấn Mở máy chiếu và chọn màn hình người dẫn sẽ đọc: kịch bản lấp kín màn hình đó từ mép này sang mép kia. Bật lật gương cho kính bán phản xạ, nơi hình phản chiếu nếu không sẽ bị ngược. Máy chiếu có điều khiển phát, thanh tiến trình và phím riêng cho người đang đọc.","docs.projector.p2":"Bản xem trước và máy chiếu dàn kịch bản cùng một chiều rộng và co giãn cho vừa, nên ngắt dòng ở cùng chỗ. Trước khi quay, hãy kiểm tra chữ lật gương đọc đúng qua kính của chính bạn.","docs.mirror.p1":"Để hiển thị kịch bản trên điện thoại, máy tính bảng hay máy tính xách tay thứ hai, mở Cài đặt → Mạng → Phản chiếu vào mạng của tôi và đánh dấu Phản chiếu kịch bản tới các thiết bị trong mạng của tôi. Đánh dấu cả Cho phép thiết bị khác, không chỉ máy tính này — nếu không, bản phản chiếu chỉ trả lời trên chính máy này — rồi nhấn Áp dụng. Một liên kết và mã QR hiện ra: quét mã, hoặc mở liên kết trong trình duyệt trên cùng mạng.","docs.mirror.p2":"Bản phản chiếu theo cùng một bộ máy, nên mọi thiết bị ở cùng một từ với người điều khiển. Mỗi thiết bị tự đặt cỡ chữ bằng A− và A+ mà không làm thay đổi màn hình của người khác.","docs.mirror.p3":"Trang được chính ứng dụng phục vụ, trực tiếp tới các thiết bị của bạn — không bao giờ qua trang web này, mà dù sao trình duyệt cũng không cho trang web này chạm tới một thiết bị trong mạng của bạn. Nó chỉ đọc: không trình duyệt nào có thể bắt đầu, dừng, tua hay sửa bất cứ thứ gì. Liên kết mang một khóa thay đổi mỗi lần ứng dụng khởi động. Đây là HTTP thường, nên khóa không được mã hóa trên đường truyền: hãy dùng trên mạng bạn tin cậy, không phải Wi-Fi công cộng.","docs.mirror.p4":"Nếu thiết bị không kết nối được: kiểm tra cả hai công tắc; bảo đảm thiết bị ở cùng mạng, không dùng dữ liệu di động hay mạng khách tách biệt các thiết bị; cho phép ứng dụng qua tường lửa cho mạng riêng khi hệ thống hỏi; và nếu Cài đặt báo bản phản chiếu không khởi động được, hãy đổi cổng và nhấn Áp dụng lần nữa.","docs.readAloud.p1":"Đánh dấu Đọc to bằng bộ tổng hợp giọng nói của hệ điều hành để nghe kịch bản bằng chính giọng của hệ thống: Windows OneCore hoặc SAPI, macOS AVSpeechSynthesis, hoặc Speech Dispatcher hay espeak-ng trên Linux. Ứng dụng không kèm giọng đọc nào.","docs.readAloud.p2":"Điều khiển phát, thanh tiến trình và một cú nhấp vào từ sẽ điều khiển giọng đọc, và phần đánh dấu đi theo nó — từng từ một ở nơi hệ thống báo ranh giới từ, theo nhịp của bạn ở nơi khác. Khoảng dừng thành những khoảng lặng ngắn, và -- không bao giờ được đọc thành \"gạch ngang\".","docs.readAloud.p3":"Đọc to chỉ dành cho bản xem trước: nó không bao giờ di chuyển máy chiếu. Hộp đánh dấu bị khóa khi một lượt đọc đang phát hoặc tạm dừng, cho đến khi bạn nhấn Dừng. Hãy kiểm tra nó phát được tiếng trên máy tính bạn sẽ dùng để trình bày, nhất là trên Linux.","docs.autocomplete.p1":"Khi bạn viết, phần còn lại của từ hiện mờ phía trước con trỏ; gõ xong một từ và nhấn cách, ứng dụng có thể gợi ý cả một cụm từ thông dụng. Tab chấp nhận, Esc bỏ qua, còn gõ tiếp thì phớt lờ nó.","docs.autocomplete.p2":"Mỗi ngôn ngữ trong 18 ngôn ngữ có danh sách từ và cụm từ riêng — tổng cộng 463.985 từ và 344.891 cụm từ — nằm trong ứng dụng, và chỉ ngôn ngữ bạn đang viết được nạp. Trong Cài đặt → Trình soạn thảo, bật hoặc tắt và chọn ngôn ngữ cho nó, có thể khác ngôn ngữ của ứng dụng.","docs.autocomplete.p3":"Danh sách được xây dựng từ bộ câu Tatoeba (CC BY 2.0 FR), được ghi công trong tệp NOTICE đi kèm ứng dụng. Đây là tra từ điển — tức thì, đoán trước được và ngoại tuyến, không có mô hình nào.","docs.dictation.p1":"Mở Cài đặt → Giọng nói, đánh dấu Viết kịch bản bằng giọng nói và nhấn Áp dụng. Một nút ghi hình tròn xuất hiện phía trên kịch bản: nhấn và nói, và những gì bạn nói được viết vào chỗ con trỏ. Nhấn lần nữa để dừng; micrô chỉ mở trong khoảng giữa.","docs.dictation.p2":"Văn bản đọc chính tả là văn bản kịch bản bình thường, và Ctrl+Z rút lại một điều bạn đã nói, không phải cả phiên. Hãy chuẩn bị chỉnh lại dấu câu và tên riêng: đây là cách nhanh để có bản nháp, không phải kịch bản hoàn chỉnh.","docs.dictation.p3":"Đọc chính tả chỉ hiểu tiếng Anh. Nó dùng Vosk, một bộ nhận dạng giọng nói mã nguồn mở, với một mô hình giọng nói tiếng Anh nhỏ — một mạng nơ-ron đã huấn luyện khoảng 40 MB — đi kèm trong ứng dụng. Nó chạy trên máy tính của bạn, hoạt động không cần kết nối, không tải lên hay tải xuống gì, và không lưu gì ngoài văn bản bạn thấy. Nó tắt cho đến khi bạn bật. Nếu kịch bản đang được phản chiếu ra mạng, các từ đọc chính tả tới các thiết bị đó ngay khi được viết, giống như khi gõ.","docs.settings.p1":"Trong Cài đặt → Giao diện, đặt phông chữ, độ đậm và màu chữ, lề hai bên, giãn dòng và vị trí của đường dẫn đọc; cỡ chữ nằm trong mục Đọc. Chúng áp dụng cùng lúc cho bản xem trước, máy chiếu và bản phản chiếu qua mạng.","docs.settings.p2":"Cài đặt hoạt động trên bản nháp: không gì thay đổi cho đến khi bạn nhấn Áp dụng, và Hủy khôi phục những gì bạn đã có. Chọn một trong 18 ngôn ngữ, hoặc Giống hệ thống của tôi. Giao diện là Tối, Sáng hoặc Giống hệ thống của tôi; bề mặt đọc luôn giữ độ tương phản cao dù bạn chọn gì.","docs.settings.p3":"Khi bật Thu nhỏ xuống khay hệ thống, trong Cài đặt → Chung, thu nhỏ sẽ đưa ứng dụng xuống khay thay vì thanh tác vụ. Xem lại phần giới thiệu, cũng trong Chung, phát lại phần giới thiệu chào mừng.","docs.access.p1":"Lần đầu ứng dụng mở, sau phần giấy phép, một phần giới thiệu bốn bước cho thấy trình soạn thảo và dấu khoảng dừng, điều khiển nhịp và máy chiếu. Bỏ qua, Esc hoặc nhấp ra ngoài sẽ đóng nó hẳn; Cài đặt → Chung → Xem lại phần giới thiệu sẽ mang nó trở lại.","docs.access.p2":"Mọi điều khiển đều hiện vòng tiêu điểm khi bạn đến bằng bàn phím. Tab ở yên trong hộp thoại đang mở, Esc đóng nó, và tiêu điểm trở về nút đã mở nó. Thanh tiến trình là thanh trượt thật: phím mũi tên dịch một ký tự, Page Up và Page Down một màn hình, còn Home và End về hai đầu.","docs.access.p3":"Nếu hệ thống yêu cầu giảm chuyển động, hiệu ứng động và làm mờ được bỏ đi trong khi kịch bản vẫn cuộn; với giảm độ trong suốt, hộp thoại làm tối nền thay vì làm mờ.","docs.problems.p1":"Khi có sự cố mà ứng dụng có thể báo cho bạn, thông báo sẽ có nút Báo cáo bên cạnh. Sau một lần ứng dụng bị sập, lần khởi động tiếp theo hiện một dải có Báo cáo và Bỏ qua.","docs.problems.p2":"Báo cáo mở trang báo cáo của Freally Teleprompt trong trình duyệt, với thông tin kỹ thuật đã điền sẵn: bạn có thể đọc nhưng không thể sửa. Thêm điều bạn đang làm và, nếu muốn, một địa chỉ email. Không gì được gửi trừ khi bạn nhấn Gửi trên trang đó, và không bao giờ có gì được gửi ngầm.","docs.problems.p3":"Mỗi lần khởi động, ứng dụng hỏi GitHub một lần xem có phiên bản mới hơn không. Nếu có, bạn thấy số phiên bản và ghi chú phát hành rồi chọn có hoặc không; bản cập nhật được kiểm tra bằng khóa ký có sẵn trong ứng dụng trước khi cài. Khi ngoại tuyến hoặc đã cập nhật, nó im lặng. Kiểm tra bản cập nhật trên thanh công cụ sẽ hỏi lại bất cứ lúc nào.","docs.privacy.p1":"Không tài khoản và không đo lường từ xa. Kịch bản của bạn là các tệp .ftscript trên máy tính, ở nơi bạn lưu, và tác giả ứng dụng không bao giờ nhận chúng.","docs.privacy.p2":"Yêu cầu duy nhất của ứng dụng tới internet là kiểm tra cập nhật, không gửi kịch bản, cài đặt hay mã định danh nào. Một báo cáo sự cố chỉ rời đi từ trang báo cáo trong trình duyệt của bạn, khi bạn nhấn Gửi. Máy chiếu và bản phản chiếu qua mạng chỉ ở trên màn hình và trong mạng của chính bạn.","docs.privacy.p3":"Học máy chỉ được dùng ở một chỗ: mô hình giọng nói của đọc chính tả, chạy trên máy của bạn và tắt cho đến khi bạn bật. Tự động hoàn thành là tra từ điển, đọc to dùng chính giọng của hệ thống, và không điều gì bạn gõ hay nói được gửi tới dịch vụ AI.","kit.skip":"Chuyển đến nội dung","kit.nav.site":"Trang web","kit.nav.home":"Trang chủ","kit.nav.features":"Tính năng","kit.nav.documentation":"Tài liệu","kit.nav.changelog":"Nhật ký thay đổi","kit.nav.language":"Ngôn ngữ","kit.nav.allApps":"Tất cả ứng dụng Freally","kit.cta.features":"Xem mọi tính năng","kit.cta.docs":"Đọc tài liệu","kit.price":"Freally Teleprompt hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán.","kit.noDownloads":"Hiện chưa có bản tải xuống, và mã nguồn là riêng tư.","kit.label.overview":"Tổng quan","kit.label.inside":"Bên trong","kit.label.roadmap":"Lộ trình","kit.ladder.done":"Xong","kit.ladder.planned":"Đã lên kế hoạch","kit.ladder.goal":"Mục tiêu","kit.label.honesty":"Trung thực","kit.family.label":"Gia đình Freally","kit.family.title":"<span class=\"hl-muted\">Một gia đình.</span> <span class=\"hl-bright\">Tám ứng dụng.</span>","kit.cta.label":"Những gì đã thay đổi","kit.cta.title":"<span class=\"hl-muted\">Mỗi phiên bản,</span> <span class=\"hl-bright\">đều được ghi lại.</span>","kit.cta.lede":"Nhật ký thay đổi liệt kê mọi thứ đã thay đổi trong Freally Teleprompt, theo từng phiên bản, bằng cả mười tám ngôn ngữ.","kit.cta.changelog":"Đọc nhật ký thay đổi","kit.footer.thisApp":"Ứng dụng này","kit.footer.family":"Gia đình Freally","kit.footer.home":"Freally Products","kit.status.devVersion":"Đang phát triển · v1.5.0","kit.head.features":"<span class=\"hl-muted\">Mọi thứ nó làm được,</span> <span class=\"hl-bright\">đặt cạnh nhau.</span>","kit.label.numbers":"Qua các con số","kit.label.free":"Miễn phí hôm nay","kit.label.compare":"So sánh","kit.label.principles":"Nguyên tắc","kit.label.limits":"Giới hạn","kit.states.title":"Ý nghĩa của các trạng thái","kit.states.done":"đã dựng và gắn thẻ, nhưng không phải bản tải xuống trên trang này","kit.states.planned":"vẫn chưa được xây dựng","kit.states.goal":"phiên bản mà con đường này hướng tới","kit.states.ladder":"Xem mọi nấc trên con đường","kit.head.documentation":"<span class=\"hl-muted\">Cách hoạt động,</span> <span class=\"hl-bright\">từng bước một.</span>","kit.search.placeholder":"Tìm kiếm trong tài liệu","kit.docs.contents":"Mục lục","kit.head.changelog":"<span class=\"hl-muted\">Mọi thay đổi,</span> <span class=\"hl-bright\">theo từng phiên bản.</span>","kit.changelog.lede":"Mới nhất trước: mọi thứ đã thay đổi trong Freally Teleprompt, bằng mọi ngôn ngữ của trang này.","kit.changelog.versions":"Phiên bản","kit.changelog.unreleased":"Chưa phát hành","kit.search.none":"Không có gì trên trang này khớp với điều đó.","changelog.69c6a54708de":"<span class=\"release__meta\"><span class=\"release__ver\">Chưa phát hành</span></span>","changelog.c205924de0fe":"Tài liệu","changelog.3ba1bf71dedb":"<strong>Website đã được dựng lại</strong> theo thiết kế của gia đình Freally, và nói cả 18 ngôn ngữ của ứng dụng — kể cả nhật ký thay đổi này. Nó không cung cấp bản tải xuống.","changelog.184abbf86c34":"<span class=\"release__meta\"><span class=\"release__ver\">v1.5.0</span></span><span class=\"release__title\">5 tháng 8 năm 2026</span>","changelog.4a6a7a1ffbc7":"Mọi thứ trong phòng đều có thể điều khiển máy nhắc chữ.","changelog.6b02e0d363a4":"Đã thêm","changelog.21717d79a98c":"<strong>Bàn đạp chân và bút trình chiếu.</strong> Bàn đạp là cách máy nhắc chữ thực sự được điều khiển khi quay — tay bạn đặt trên máy quay, không phải bàn phím. Mở <strong>Phím tắt</strong>, nhấn vào phím gán bạn muốn đổi, rồi đạp bàn đạp: thứ nó gửi đi chính là thứ được lưu, không cần trình điều khiển, không cần thiết lập. Hầu hết bàn đạp và bút trình chiếu gửi <code>F13</code>–<code>F24</code> chính vì không gì khác dùng chúng, và giờ chúng được gán như mọi phím khác.","changelog.87aef9902031":"<strong>Phím vẫn hoạt động khi Freally Teleprompt không ở phía trước.</strong> Người điều khiển thường đang ở trong ứng dụng camera, DAW hoặc OBS, nên mọi lệnh phát có thể có thêm một phím gán thứ hai mà hệ điều hành chuyển tới dù bạn đang ở đâu.","changelog.d6a3a80ffa2c":"<strong>Không gì bị giữ cho đến khi bạn yêu cầu.</strong> Mặc định không đăng ký phím toàn hệ thống nào — lấy một phím khỏi mọi chương trình khác khi chưa được mời không phải việc ứng dụng nên làm ở lần chạy đầu.","changelog.e134c7c903f4":"<strong>Phím bị từ chối sẽ nói rõ.</strong> Nếu chương trình khác đã giữ tổ hợp phím, dòng đó cho bạn biết, kèm lý do. Dưới Wayland, vốn hoàn toàn không cho ứng dụng giữ phím toàn hệ thống, hộp thoại cũng nói vậy thay vì hiển thị một phím gán lặng lẽ không làm gì.","changelog.dfedb41c2cf4":"<strong>Một bản đồ có thể tìm kiếm và gán lại cho mọi lệnh</strong>, có phát hiện xung đột — tìm theo tên lệnh, hoặc theo chính phím đó khi bạn muốn biết <code>F13</code> đang làm gì. Xóa một phím gán, hoặc khôi phục mặc định đi kèm, bất cứ lúc nào.","changelog.b74f3602a847":"<strong>Một bảng điều khiển tất cả.</strong> Bản xem trước, cửa sổ máy chiếu, bàn đạp và phím nóng toàn hệ thống đều đọc cùng các phím gán, nên đổi một phím là đổi ở mọi nơi cùng lúc — kể cả máy chiếu của người dẫn, vốn theo phím gán mới mà không cần mở lại.","changelog.3573af4808a8":"Phím cách, các phím mũi tên và Home vẫn gõ bình thường khi bạn đang viết kịch bản: một phím đơn chỉ chạy lệnh của nó khi bạn không ở trong trình soạn thảo.","changelog.1246fc93bca0":"Đã sửa","changelog.07ff9553768e":"<strong>Nhập tài liệu (tính năng <code>Import</code> của 1.4.0), với chủ đề: một bộ chuyển đổi lặng lẽ thay đổi kịch bản của bạn còn tệ hơn một bộ chuyển đổi từ chối nó.</strong>","changelog.0ec8d88f6052":"<strong>PDF không còn tự nhận là biết mình đã bỏ sót gì.</strong> Mọi định dạng khác được đọc bằng cách duyệt một mô hình tài liệu, nên &quot;không còn gì bị bỏ sót&quot; là điều bộ nhập thực sự kiểm tra được. PDF không có cấu trúc như vậy — ở đó, danh sách trống có nghĩa là <em>chúng tôi không thể biết</em> — và nói khác đi là một sự trấn an sai lầm ở đúng định dạng hay chứa hình và chú thích cuối trang nhất.","changelog.7ea47b0b9557":"<strong>Hộp văn bản của Word không còn bị báo là hình bị thiếu.</strong> Văn bản trong đó vẫn được nhập từ trước tới nay, đồng thời lại bị đếm là một hình bị bỏ. Giờ nó trở thành một đoạn riêng thay vì bị chèn vào dòng tình cờ neo nó — &quot;chúng ta chuyển MÁY QUAY sang cảnh rộng&quot; không phải điều tài liệu viết.","changelog.9962e4f893ac":"<strong>Hình ảnh và đầu trang được đếm một lần, và chỉ ở nơi được dùng.</strong> Một bức ảnh từng bị báo thành hai, và Word ghi ba đầu trang và ba chân trang vào mọi tài liệu dù có dùng hay không — nên một đầu trang bị báo thành sáu. Người điều khiển đọc &quot;Hình bị bỏ: 2&quot; sẽ đi tìm một bức hình thứ hai chưa từng tồn tại.","changelog.07aaaf2b256f":"<strong>Ký tự mà Word lưu dưới dạng phần tử không còn bị mất lặng lẽ</strong> — <code>co‑operate</code> từng được nhập thành <code>cooperate</code>. Một glyph từ phông ký hiệu giờ được đếm là thứ bị bỏ thay vì bị đoán, vì điểm mã của nó là chỉ mục trong một phông chữ, không phải một ký tự.","changelog.c15eb04425e7":"<strong>Tệp tự nhận là Unicode nhưng không phải giờ sẽ được báo.</strong> Một số công cụ đóng ba byte đánh dấu UTF-8 rồi vẫn ghi văn bản Tây Âu; tệp đó từng được nhập với mọi ký tự có dấu bị thay bằng <code>�</code> <strong>và</strong> báo cáo nói rằng không gì bị bỏ — đúng lỗi mà ghi chú bảng mã tồn tại để ngăn, xảy ra qua con đường duy nhất bỏ qua bước kiểm tra.","changelog.3e2d09e4e749":"<strong>Chuẩn hóa dấu gạch ngang vẫn không thể bịa ra khoảng dừng.</strong> Một dấu cách độ rộng bằng không hay một byte đánh dấu lạc giữa hai dấu gạch — thứ văn bản lấy từ web và PDF thường mang theo — đã tách chuỗi làm đôi, và <code>a —​— b</code> bị nhập thành một khoảng ngắt <code> -- </code> không ai viết. RTF cũng rẽ sai như vậy theo một đường khác.","changelog.cdc8dc821ad8":"<strong>RTF: hình ảnh hay đối tượng nhúng không còn lọt vào kịch bản.</strong> Dữ liệu nhị phân từng bị đọc như thể là văn bản, nên byte <code>}</code> đầu tiên trong đó — mà dữ liệu nhị phân bất kỳ chứa khoảng một lần mỗi 256 byte — kết thúc việc bỏ qua quá sớm và đổ phần còn lại vào kịch bản.","changelog.c62855d7561c":"<strong>RTF: emoji và các ký tự ngoài mặt phẳng cơ bản được giữ lại.</strong> Chúng đến dưới dạng hai nửa của một cặp thay thế, và không nửa nào tự nó là một ký tự, nên cả hai từng bị bỏ. Dấu cách không ngắt và dấu gạch nối không ngắt giờ cũng được nhập đúng là chính chúng.","changelog.456985ca40d6":"<strong>Ứng dụng không còn treo khi đang đọc tài liệu.</strong> Một tệp PDF lớn từng có thể giữ cửa sổ đứng tới chín mươi giây.","changelog.5ff5476a8e49":"<strong>Một lần nhập chậm không còn rơi vào nhầm hộp thoại.</strong> Đóng nó, mở lại, chọn tệp khác, và kết quả của tài liệu đầu tiên từng đến và tráo báo cáo, bản xem trước <em>và</em> tên — nên nhấn Nhập lại lưu một kịch bản bạn không chọn, dưới một cái tên đã đổi ngay dưới tay bạn.","changelog.ca076d4847ef":"<strong>Lần lưu thất bại không còn để lại phần thừa.</strong> Nếu ghi thất bại — thư mục chỉ đọc, ổ đầy, tệp bị trình đồng bộ khóa — một kịch bản trống từng bị bỏ lại trong thư viện dưới tên bạn chọn, và nhập lại thì báo lỗi &quot;đã có kịch bản tên đó&quot;. Bạn phải xóa nó bằng tay. Thao tác hoàn nguyên không bao giờ che giấu lỗi thật.","changelog.81f5afe81f74":"<strong>Tìm và thay thế (tính năng <code>Find</code> của 1.4.0)</strong>","changelog.df4d2a98d916":"<strong>Thay thế giờ sửa kịch bản như nó đang là, không phải như nó vừa là một lúc trước.</strong> Cả Thay thế lẫn Thay tất cả từng được tính trên một bản sao chậm hơn trình soạn thảo một vòng trao đổi — nên một câu đọc chính tả đến trong khoảng đó bị ghi đè và mất, và vị trí một kết quả có thể chỉ vào sai ký tự.","changelog.0cc222aab642":"<strong>Thay bằng văn bản có chứa chính thứ bạn tìm giờ sẽ tiến về phía trước.</strong> Thay &quot;the&quot; bằng &quot;there&quot; từng biến một từ thành &quot;therere&quot; sau ba lần nhấn trong khi hai từ kia vẫn nguyên, và bộ đếm hiện &quot;1 trên 3&quot; suốt từ đầu đến cuối.","changelog.fa5b9ccac936":"<strong>Báo cáo tập dượt (chế độ tập dượt của 1.3.0)</strong>","changelog.e72cfed29d53":"<strong>Một tiêu đề lạc không còn làm sập báo cáo.</strong> Một kịch bản mười hai đoạn mang một <code># Title</code> duy nhất từ lần nhập Markdown — hoặc một dòng danh sách cảnh quay ghi <code>#3 CAMERA B</code> — từng rơi từ mười hai dòng xuống còn hai, mất đi thời gian từng đoạn mà báo cáo tồn tại để cung cấp. Một dấu mốc đặt tên cho kịch bản; nó không chia kịch bản thành các phần.","changelog.cc295a583a87":"<span class=\"release__meta\"><span class=\"release__ver\">v1.4.0</span></span><span class=\"release__title\">4 tháng 8 năm 2026</span>","changelog.4f39388d525b":"Đưa kịch bản vào, và định hướng bên trong nó.","changelog.2bfa1e157a29":"<strong>Mở tệp người ta gửi cho bạn.</strong> Trước nay, cách duy nhất để văn bản đến máy nhắc chữ là gõ và dán, mà chẳng kịch bản nào đến theo cách đó. <strong>Nhập</strong> trên thanh công cụ đọc <strong>Word (<code>.docx</code>), RTF, PDF, văn bản thuần và Markdown</strong> và biến chúng thành văn bản nhắc chữ sạch: giữ các đoạn, làm phẳng chữ đậm, phông chữ và màu, chuẩn hóa ngoặc kép cong, gạch ngang dài và dấu ba chấm, và tệp lưu sai bảng mã được đọc và báo lại thay vì hiển thị thành ký tự lỗi.","changelog.514edf636361":"<strong>Nó cho bạn biết những gì không mang sang được</strong> — hình ảnh, chú thích cuối trang, bình luận, đầu trang và chân trang, địa chỉ liên kết, đối tượng nhúng, mỗi thứ kèm số lượng. Một bộ chuyển đổi lặng lẽ bỏ chúng là thứ bạn chỉ phát hiện ra khi đang quay.","changelog.b9c0ccd7f34c":"<strong>Không gì được lưu cho đến khi bạn đồng ý.</strong> Bạn xem văn bản và báo cáo, đặt tên cho kịch bản, và chỉ khi đó một tệp mới xuất hiện trong thư viện — và một lần nhập sẽ không bao giờ ghi đè kịch bản đã có.","changelog.d2b1a7638b2a":"Chuẩn hóa dấu gạch không bao giờ bịa ra khoảng dừng: một <code>—</code> in ấn trở thành dấu gạch nối thường, và hai dấu liền nhau không biến thành ký hiệu khoảng ngắt <code> -- </code> của ứng dụng này. Một tệp <code>.txt</code> bạn viết với khoảng ngắt thật vẫn giữ chúng.","changelog.90b7cc8211d3":"<strong>Dấu mốc phần, kèm danh sách nhảy.</strong> Mọi dòng bắt đầu bằng <code>#</code> — <code># Verse 2</code>, <code># Q&amp;A</code> — đều là một mốc, cũng như mọi dòng là một trong những từ bỏ qua của bạn (<code>[Chorus]</code>, <code>Bridge</code>). Chúng hiện trong danh sách nhảy cạnh thanh tiến trình, được vạch trên chính thanh đó, và <strong>tiếp / trước</strong> đi qua chúng. Không có gì phải cấu hình, và một kịch bản Markdown được nhập đến kèm danh sách đã dựng sẵn.","changelog.697fb23f904c":"Trước đi về đầu phần bạn đang ở, rồi lùi xa hơn — giống cách một nút bài trước hoạt động.","changelog.ce1cd4f6f1f3":"<strong>Tìm và thay thế</strong> (<code>Ctrl+F</code>), trong phạm vi kịch bản đang mở: đếm kết quả trực tiếp, phân biệt hoa thường, chỉ nguyên từ, thay thế và thay tất cả. Kết quả hiện tại được làm sáng trong trình soạn thảo mà không kéo việc gõ của bạn ra khỏi ô tìm kiếm, và thay tất cả được hoàn tác bằng <strong>một</strong> lần nhấn Ctrl+Z.","changelog.164dc61c0ad5":"<strong>Thống kê kịch bản</strong>, bên dưới ước tính thời gian đọc: số từ, số ký tự, và cảnh báo khi một dòng dài đến mức là cả một đoạn bị ngắt dòng. Số đếm chỉ tính những gì thực sự được <strong>trình diễn</strong> — nhãn bị bỏ qua và ký hiệu khoảng dừng không tính, nên chúng khớp với thời lượng ngay bên cạnh.","changelog.2a6141e43be0":"Đã thay đổi","changelog.24b7a7366360":"Các phần của báo cáo tập dượt giờ được chia theo dấu mốc ngoài nhãn bỏ qua, nên một kịch bản viết với tiêu đề <code>#</code> được tập dượt theo từng phần mà không cần cấu hình từ khóa nào. Một phần được đặt tên không kèm trang trí: <code>[Verse 1]</code> hiện thành <em>Verse 1</em>.","changelog.8f6fb4eb7f42":"Bảo mật","changelog.9dc7532525e8":"Mọi trình phân tích tài liệu chạy trong một <strong>tiến trình riêng</strong>. Ba trong năm định dạng được đọc bởi các crate bên thứ ba trên một tệp ứng dụng không tự viết, và bản phát hành dừng hẳn khi gặp panic — nên một tệp PDF hỏng có thể đã làm sập máy nhắc chữ giữa lượt đọc. Cách này cũng đặt giới hạn thời gian cho công việc và giữ bộ nhớ của một trình phân tích mất kiểm soát ở ngoài ứng dụng.","changelog.bbb6d70966f6":"Tệp tạm của lần nhập được tạo trong một thư mục mới tạo có tên không thể đoán, và trên Unix chỉ chủ sở hữu mới vào được.","changelog.0fdcda0b6a1e":"<span class=\"release__meta\"><span class=\"release__ver\">v1.3.0</span></span><span class=\"release__title\">3 tháng 8 năm 2026</span>","changelog.4245679cbf6a":"Đọc đúng giờ — và những từ không nên được tính.","changelog.3a8bc8eb9047":"<strong>Gõ một nhịp độ, và ứng dụng học nhịp của bạn.</strong> BPM luôn được đổi thành tốc độ đọc bằng một con số: bạn đọc được bao nhiêu ký tự trong một phách. Trước đây đó là phỏng đoán — cùng một phỏng đoán cho ca sĩ hát ballad và rapper, vốn cách nhau cả một bậc độ lớn. <strong>Cài đặt → Định thời</strong> giờ cho bạn gõ theo đúng nhịp bạn biểu diễn, và đo con số đó dựa trên tốc độ đọc của chính bạn thay vì giả định.","changelog.b94cb35d22f5":"Một lần hiệu chỉnh khiến một phần dải âm nhạc nằm ngoài tầm của bộ máy sẽ <strong>thu hẹp dải mà ô BPM đưa ra</strong> thay vì cho bạn thấy những con số mà nó sẽ lặng lẽ đổi sau lưng bạn.","changelog.4b0c4241773f":"<strong>Máy đếm nhịp.</strong> Một tiếng gõ tùy chọn ở mỗi phách khi kịch bản cuộn, nhấn mạnh ở phách đầu ô nhịp, với phần đếm ngược trước khi bắt đầu kiêm luôn phần đếm vào. Ứng dụng tự tổng hợp âm thanh — không có tệp âm thanh nào trong bộ cài và không gì được tải về. Nó được lên lịch theo đồng hồ âm thanh từ số thứ tự của từng phách, nên không bị trôi so với việc cuộn: đo trong một lượt đọc mười phút ở nhịp nhanh nhất ứng dụng cho phép, tiếng gõ cuối cùng vẫn chính xác.","changelog.a0c53f6c5b09":"<strong>Bộ đếm ô nhịp và phách</strong>, cạnh bề mặt đọc, với <strong>vạch nhịp kẻ trên thanh tiến trình</strong> — để &quot;mười sáu ô nhịp&quot; là thứ bạn nhìn thấy chứ không phải đếm trong đầu. Cả hai chỉ hiện khi bạn làm việc theo một nhịp độ.","changelog.84aa1a93cd53":"<strong>Chế độ tập dượt, kèm báo cáo thời gian.</strong> Đọc hết kịch bản và ứng dụng cho bạn biết, từng phần một, lẽ ra mất bao lâu so với thực tế, và đề xuất nhịp bạn đã thực sự đọc. Nó ghi lại <strong>thời gian và không gì khác</strong> — không có micrô và không có đường âm thanh nào, điều được một bài kiểm thử khẳng định chứ không chỉ hứa ở đây.","changelog.3bcd3e611ff3":"<strong>Một cảnh báo nhịp nhẹ nhàng</strong> khi tập dượt, khi lượt đọc đã lệch khỏi kế hoạch hơn vài giây — để một phần bị kéo dài lộ ra trước khi kết thúc chứ không phải sau đó.","changelog.440434188c4b":"<strong>Những từ bạn đọc nhưng không trình diễn.</strong> Đặt &quot;Chorus&quot;, &quot;Verse&quot; hay &quot;Bridge&quot; vào <strong>Cài đặt → Định thời</strong> và một dòng chỉ gồm một trong số đó — <code>Chorus</code>, <code>[Verse 1]</code>, <code>## Bridge</code> — <strong>hoàn toàn không tốn thời gian</strong>, nên lời bài hát của bạn vẫn rơi đúng ô nhịp bạn đã viết. Cùng từ đó nằm trong một dòng thật chỉ bỏ qua chính nó, nên &quot;back to the chorus now&quot; vẫn giữ thời gian của nó. Chúng vẫn ở trên màn hình, mờ đi, và chế độ đọc to không bao giờ đọc chúng.","changelog.c06854290d9c":"<span class=\"release__meta\"><span class=\"release__ver\">v1.2.0</span></span><span class=\"release__title\">2 tháng 8 năm 2026</span>","changelog.b16edf96208e":"Nút ghi, và điều gì xảy ra với lời nói sau khi bạn nói ra.","changelog.e03e88337492":"<strong>Nút ghi là một cái nút, không phải một câu.</strong> Giờ nó là một hình tròn có biểu tượng bên trong — <strong>●</strong> để ghi, <strong>■</strong> để dừng — với hướng dẫn nằm bên cạnh chứ không ở trong, nên nút thôi thay đổi độ rộng khi bạn dùng. Màu của nó theo con trỏ của bạn cũng như theo trạng thái: rê chuột lên nút ghi thì nó chuyển xanh lá, còn khi đang ghi, rê chuột lên sẽ làm nó đỏ. Di chuột đi thì nó trở lại như cũ mà không đổi việc nó sẽ làm.","changelog.f7a0e2da64e7":"<strong>Từ đọc chính tả giờ đi qua trình soạn thảo</strong>, đúng nơi lẽ ra chúng luôn phải đi qua. Từ đó dẫn tới ba điều, và mỗi điều trước đây là một lỗi thật:","changelog.8e6453161785":"<strong>Hoàn tác rút lại một điều bạn đã nói</strong>, không phải cả phiên. Trước đây Ctrl+Z nhảy qua mọi thứ bạn đã đọc chính tả chỉ trong một bước.","changelog.c4b4bb124914":"<strong>Văn bản bạn gõ trong lúc ghi được giữ lại.</strong> Trước đây điều tiếp theo bạn nói sẽ ghi đè lên nó.","changelog.f9033b43c6e5":"<strong>Lời nói xuất hiện ở chỗ con trỏ</strong>, không phải lúc nào cũng ở cuối kịch bản.","changelog.d766eb074a43":"Đọc chính tả từng báo đã sẵn sàng khi <strong>thư mục</strong> mô hình giọng nói tồn tại, ngay cả khi mô hình bên trong bị thiếu hay chép dở — khiến trên màn hình có một nút ghi chỉ có thể thất bại khi nhấn. Giờ nó kiểm tra đúng một tệp mà bộ nhận dạng không thể khởi động nếu thiếu.","changelog.4b11a58f4f52":"Khi cài trên một <strong>ổ đĩa không có ký tự ổ</strong> (ổ được gắn vào một thư mục), đường dẫn mô hình đưa cho bộ nhận dạng từng bị biến thành một đường dẫn chẳng trỏ tới đâu. Giờ nó trỏ tới mô hình. Việc bộ nhận dạng sau đó có nạp được nó hay không chưa được thử trên cấu hình như vậy — nhưng nếu lỗi xảy ra ở đó, nó sẽ nói mô hình nào không mở được, thay vì lặng lẽ tìm ở một nơi hoàn toàn khác.","changelog.c0965fe505ea":"Văn bản chèn khi con trỏ ở <strong>ngay đầu</strong> kịch bản có thể rơi xuống cuối. Trình soạn thảo không đọc được vị trí con trỏ nằm trên toàn bộ kịch bản thay vì trong một dòng của nó, và trả lời bằng độ dài của tất cả — nên nội dung dán hoặc một dòng đọc chính tả bị đưa xuống cuối.","changelog.15f80b1047f4":"Đọc chính tả có thể báo <strong>không khả dụng dù đã cài một mô hình hoàn toàn tốt</strong>: một <code>vosk-model-en</code> lạc hay chép dở trong thư mục dữ liệu của bạn được ưu tiên hơn mô hình có sẵn trong ứng dụng, rồi bị từ chối vì không đầy đủ. Giờ ứng dụng bỏ qua thư mục không dùng được và dùng mô hình đi kèm nó.","changelog.4ecc1ea9414e":"<code>npm run dev:vosk</code> cho người đóng góp — một lần chạy phát triển thực sự đọc chính tả được. Nếu không, đọc chính tả chỉ có trong bản phát hành, khiến việc phát triển nó bất tiện.","changelog.9ef45f3d9beb":"Ô tìm kiếm của trang tài liệu giờ tìm thấy <strong>đọc chính tả</strong> — tính năng ra mắt ở 1.1.0 nhưng không có trong chỉ mục, nên tìm nó chẳng ra gì. Theo chiều ngược lại, những kết quả chỉ có thể dẫn tới lỗi 404 đã bị bỏ: chỉ mục dùng chung liệt kê năm ứng dụng Freally chưa có trang, chiếm 39 trong 109 mục.","changelog.1569fac6a9e5":"<code>THIRD-PARTY.md</code> ghi nhận <strong>Vosk</strong> (bộ máy, mô hình và môi trường chạy MinGW cho Windows) cùng với các phông chữ; <code>NOTICE</code> giờ có chỉ dẫn tới mã nguồn tương ứng của môi trường chạy đó. Cả hai tệp đều nằm trong bộ cài.","changelog.a02b0fb176eb":"Ghi chú trong Cài đặt về đọc chính tả nói rõ điều gì xảy ra khi <strong>phản chiếu qua mạng nội bộ</strong> đang bật: văn bản đọc chính tả tới người xem ngay khi được viết, giống như khi gõ.","changelog.226b619dcadb":"<span class=\"release__meta\"><span class=\"release__ver\">v1.1.0</span></span><span class=\"release__title\">2 tháng 8 năm 2026</span>","changelog.d3ca2e44459c":"Một cách duy nhất để dùng giọng nói, và nó hoạt động ngay khi bạn bật.","changelog.b370d746f358":"<strong>Viết kịch bản bằng giọng nói</strong> (FT-33) — bật <strong>Đọc chính tả</strong> trong Cài đặt → Giọng nói và một nút ghi xuất hiện phía trên kịch bản. Nhấn nó và những gì bạn nói được viết vào; nhấn lần nữa để dừng.","changelog.e02d4e39e7e3":"Không cần huấn luyện hay thiết lập: mô hình giọng nói nằm sẵn trong bộ cài, nên nó hoạt động ngay khi bạn bật. Không gì được tải xuống khi chạy và không gì được gửi đi đâu — bộ nhận dạng và mô hình của nó nằm trên máy bạn, và điều đó vẫn đúng khi ngoại tuyến. Micrô chỉ mở trong lúc ghi, và từ những gì bạn nói, chỉ có chính văn bản được ghi ra tệp.","changelog.4118fb4fed0e":"Đã gỡ bỏ","changelog.9201332ddf55":"<strong>Lệnh giọng nói đã bị bỏ.</strong> Chúng bắt bạn ghi âm từng lệnh — phát, tạm dừng, nhanh hơn, chậm hơn, khoảng dừng tiếp theo, về đầu — bằng giọng của mình trước khi bất kỳ lệnh nào làm được gì, rồi giữ một nút trong lúc nói. Cho đến khi bạn ghi âm xong, giữ nút chỉ mở micrô mà chẳng làm được gì, và không cách nào phân biệt điều đó với lỗi. Đọc chính tả bao quát cùng nhu cầu mà không cần huấn luyện gì.","changelog.8afda10a9120":"<strong>&quot;Theo dõi lượt đọc của tôi&quot; đã bị bỏ</strong> vì cùng lý do: một cách rõ ràng để dùng giọng nói tốt hơn ba cách chồng chéo nhau. Phần căn chỉnh đứng sau nó vẫn tồn tại dưới dạng thư viện và có thể quay lại với hình thức khác.","changelog.119dd324728e":"Bộ cài vì thế lớn hơn bản 1.0.0 — mô hình giọng nói khoảng 40 MB, và giờ luôn đi kèm dù bạn có dùng hay không.","changelog.9133884e4863":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0</span></span><span class=\"release__title\">2 tháng 8 năm 2026</span>","changelog.3d6b5cab67c7":"Bản phát hành công khai đầu tiên: mọi thứ từ Giai đoạn 3 (điều khiển bằng giọng nói rảnh tay) và đợt hoàn thiện của Giai đoạn 5, đóng gói thành bộ cài có chữ ký cho Windows, macOS và Linux.","changelog.880aaef19013":"<strong>Phần giới thiệu một phút</strong> (FT-50) — lần đầu bạn mở ứng dụng, bốn bước ngắn giới thiệu trình soạn thảo và dấu khoảng dừng, điều khiển nhịp và máy chiếu. Bỏ qua bất cứ lúc nào, và chạy lại khi nào bạn muốn từ <strong>Cài đặt → Chung → Xem lại phần giới thiệu</strong>.","changelog.0df57f3fd77c":"<strong>Giao diện đi theo hệ thống</strong> (FT-50) — bên cạnh Tối và Sáng giờ có <strong>Giống hệ thống của tôi</strong>, chuyển theo hệ điều hành và vẽ lại ngay khi máy bạn đổi lúc hoàng hôn. Tối vẫn là mặc định.","changelog.3d5dfaad60e5":"<strong>Lệnh giọng nói</strong> (FT-30, FT-31) — huấn luyện <strong>phát, tạm dừng, nhanh hơn, chậm hơn, khoảng dừng tiếp theo, về đầu</strong> bằng giọng của bạn (vài lần mỗi lệnh) và điều khiển máy nhắc chữ rảnh tay. Chỉ báo <strong>● Đang nghe</strong> hiện rõ mỗi khi micrô mở; chọn <strong>nhấn để nói</strong> (micrô chỉ mở khi bạn giữ nút) hoặc <strong>luôn lắng nghe</strong>. <strong>Tắt theo mặc định.</strong> Không dùng mô hình: so khớp bằng xử lý tín hiệu cổ điển với chính các bản ghi của bạn, ngay trên thiết bị.","changelog.689534aed982":"<strong>Theo giọng nói</strong> (FT-32, FT-34, FT-35) — một chế độ <strong>tùy chọn</strong> cuộn kịch bản để theo kịp khi bạn đọc to, nhận ra chính các từ của kịch bản bằng một mô hình Vosk Apache-2.0 đi kèm. Nó <strong>trả quyền về điều khiển tay</strong> ngay khi mất dấu chỗ bạn đang đọc (nên không bao giờ cuộn tới chỗ sai) và chỉ điều khiển bản xem trước của người điều khiển, không bao giờ là máy chiếu. <strong>Tắt theo mặc định</strong>, và chuyển xám kèm lý do khi chưa cài mô hình. Lớp căn chỉnh tất định quyết định bạn đang ở đâu trong kịch bản là hoàn toàn của chúng tôi và có kiểm thử đơn vị.","changelog.10a2d92eba51":"<strong>Bộ cài có chữ ký và tự cập nhật</strong> (FT-51, FT-52) — Windows (<code>.exe</code> và <code>.msi</code>), một <code>.dmg</code> đa kiến trúc cho macOS, cùng AppImage và <code>.deb</code> cho Linux, tất cả dựng từ một commit đã gắn thẻ. Bộ cập nhật trong ứng dụng kiểm tra trang phát hành, và mọi bản cập nhật được xác minh bằng một khóa ký mà ứng dụng mang theo — bản cập nhật không xác minh được sẽ bị từ chối thay vì được cài.","changelog.6831bb79a881":"<strong>Đợt hoàn thiện trợ năng cho bàn phím và trình đọc màn hình</strong> (FT-50) — mọi điều khiển nhận tiêu điểm giờ hiện vòng tiêu điểm rõ ràng; <strong>Tab</strong> ở yên trong hộp thoại đang mở thay vì lạc sang cửa sổ phía sau; đóng hộp thoại sẽ trả tiêu điểm về nút đã mở nó; và danh sách mục của Cài đặt giờ báo đúng ngăn bạn đang thực sự xem, kể cả khi ô tìm kiếm đang lọc nó. Ứng dụng cũng tôn trọng <strong>giảm chuyển động</strong> ở mọi nơi. Việc cuộn của chính kịch bản cố ý không bị cài đặt đó tác động — đó là việc ứng dụng tồn tại để làm, và bạn đã trực tiếp kiểm soát tốc độ của nó.","changelog.54a57c3147c4":"Quyền riêng tư","changelog.deae17e358ff":"<strong>Không bao giờ dùng mạng.</strong> Lệnh giọng nói không bao giờ chạm tới mạng hay ổ đĩa — âm thanh được so khớp trong bộ nhớ với chính các bản ghi của bạn, và không điều gì bạn nói được ghi ra tệp. Chế độ theo giọng nói chạy bộ nhận dạng hoàn toàn trên thiết bị; mô hình nằm trong bộ cài và không tải gì khi chạy.","changelog.0d7048033eef":"_<strong>Chế độ theo giọng nói chưa dùng được trong bản này.</strong> Bộ nhận dạng cần một mô hình giọng nói, và bản phát hành này chưa kèm mô hình — tính năng phát hiện điều đó và tự báo không khả dụng kèm lý do, thay vì thất bại khi bạn bật nó. <strong>Lệnh</strong> giọng nói không bị ảnh hưởng: chúng không cần mô hình và hoạt động ở đây. Các lớp căn chỉnh và ngữ pháp bên dưới đã hoàn chỉnh và được kiểm thử._","changelog.f8a8681a3de9":"<span class=\"release__meta\"><span class=\"release__ver\">v0.300.0</span></span><span class=\"release__title\">22 tháng 7 năm 2026</span>","changelog.49b18dafa9ac":"Tự động hoàn thành ngoại tuyến trong trình soạn thảo kịch bản: gợi ý phần còn lại của từ khi bạn gõ, bằng bất kỳ ngôn ngữ nào trong 18 ngôn ngữ, từ các danh sách từ có sẵn trong ứng dụng.","changelog.863ad5535d5a":"<strong>Tự động hoàn thành bằng chữ mờ</strong> (FT-20, FT-21) — bắt đầu một từ và phần còn lại hiện mờ phía trước con trỏ. <strong>Tab</strong> chấp nhận, <strong>Esc</strong> bỏ qua, còn gõ tiếp thì phớt lờ nó. Nó còn hoàn thành cả cụm từ thông dụng, khi bạn gõ xong một từ và nhấn cách.","changelog.342d77799f0d":"<strong>Cài đặt tự động hoàn thành</strong> — một ngăn <strong>Trình soạn thảo</strong> mới có công tắc bật/tắt và <strong>ngôn ngữ gợi ý</strong> riêng, tách khỏi ngôn ngữ của ứng dụng, vì viết kịch bản bằng một ngôn ngữ trong khi dùng ứng dụng bằng ngôn ngữ khác là chuyện bình thường.","changelog.bf3195662b89":"<strong>Bảng từ và cụm từ cho cả 18 ngôn ngữ</strong> (FT-22) — tổng cộng khoảng 464.000 từ và 345.000 cụm từ, đi kèm trong bộ cài. Chỉ ngôn ngữ bạn thực sự dùng được nạp, nên mỗi lúc ứng dụng chỉ tốn khoảng 0,5 MB bộ nhớ thay vì cả 12 MB.","changelog.9fb2fa59ae13":"<strong>Bộ chọn ngôn ngữ giờ bắt đầu bằng tiếng Anh rồi xếp theo thứ tự chữ cái theo tên gốc của từng ngôn ngữ</strong> — Deutsch, Español, Français, v.v. — và giữ nguyên thứ tự đó bất kể ứng dụng đang ở ngôn ngữ nào. Trước đây nó theo tên tiếng Anh, nên thứ tự thay đổi tùy vào ngôn ngữ bạn đã chọn.","changelog.6e805db44ddd":"<strong>Tự động hoàn thành không bao giờ chạm tới mạng.</strong> Đó là tra cứu trong các bảng nằm trong bộ cài — không mô hình, không dịch vụ, không đo lường từ xa. Không điều gì bạn gõ được gửi đi đâu, và tính năng vẫn hoạt động khi máy ngoại tuyến.","changelog.97775eaa1065":"<span class=\"release__meta\"><span class=\"release__ver\">v0.200.0</span></span><span class=\"release__title\">21 tháng 7 năm 2026</span>","changelog.fdaeb02ed57c":"Máy nhắc chữ độc lập: kịch bản bạn có thể giữ, máy chiếu cho người dẫn, điều khiển phát thật sự, và máy nhắc chữ tự đọc to.","changelog.3c1c1f577fc6":"<strong>Thư viện kịch bản</strong> (FT-10) — các tệp <code>.ftscript</code> bạn có thể tạo, mở, đổi tên và xóa, kèm danh sách gần đây và <strong>tự động lưu</strong> khi bạn gõ. Chúng là văn bản UTF-8 thuần trong một thư mục, nên kịch bản vẫn đọc được, so sánh được và cứu được trong mọi trình soạn thảo văn bản nếu một ngày ứng dụng này biến mất. Ứng dụng mở lại thứ bạn mở lần cuối.","changelog.54ba591e950e":"<strong>Chip khoảng ngắt trong trình soạn thảo</strong> (FT-11) — mỗi <code> -- </code> / <code> --2 </code> trong dòng hiện thành một viên thuốc không tách rời ghi độ dài khoảng dừng. Con trỏ chỉ đứng được trước hoặc sau nó, Backspace/Delete xóa trọn ký hiệu trong một lần nhấn, Shift+mũi tên chọn nó như một khối, sao chép/cắt mang theo văn bản <code> -- </code> thật, và kịch bản được dán vào sẽ được chuẩn hóa khoảng trắng cẩu thả. Gõ dấu gạch thứ hai sẽ tự mở rộng khoảng dừng cho bạn.","changelog.b9587c13e3c6":"<strong>Cửa sổ máy chiếu</strong> (FT-12) — mở bề mặt đọc trên bất kỳ màn hình nào được kết nối, lấp kín từ mép này sang mép kia, với <strong>lật gương</strong> cho kính bán phản xạ của máy nhắc chữ. Nó chạy trên cùng trạng thái cuộn với bản xem trước của người điều khiển, nên hai bên không bao giờ bất đồng về chỗ đang đọc, và có điều khiển phát, thanh tiến trình và phím tắt riêng cho người thực sự đọc.","changelog.d50b42582cf9":"<strong>Phản chiếu qua mạng nội bộ</strong> (FT-12) — phản chiếu kịch bản đang cuộn tới điện thoại, máy tính bảng hay máy tính xách tay thứ hai trong mạng của bạn, từ liên kết và mã QR ứng dụng hiển thị. Mỗi thiết bị tự đặt cỡ chữ mà không thay đổi những gì người khác thấy. <strong>Tắt theo mặc định</strong>, chỉ trên chính máy này cho đến khi bạn mở rõ ràng ra mạng, được bảo vệ bằng khóa tạo mới mỗi lần khởi động, và <strong>chỉ đọc</strong> — không gì trình duyệt gửi tới có thể thay đổi việc cuộn, kịch bản hay một cài đặt.","changelog.00b57b5822cd":"<strong>Điều khiển phát thật sự</strong> (FT-13) — phát / tạm dừng / dừng / tua lùi / tua tới là các nút SVG đúng nghĩa với <strong>giữ để lặp lại</strong>, một thanh tiến trình kiểu YouTube có thời gian đọc đã qua và tổng (tính cả khoảng ngắt) và xem trước từ ở bất kỳ điểm nào khi rê chuột, nhấp một từ để bắt đầu, tua bằng con lăn chuột, và phím tắt trên máy chiếu.","changelog.d3d56659d660":"<strong>Chế độ tốc độ BPM</strong> (FT-14) — hiển thị nhịp dưới dạng số ký tự mỗi giây hoặc <strong>BPM (20–250)</strong> cho lối đọc theo nhạc. Bộ máy vẫn tính bằng ký tự mỗi giây suốt từ đầu đến cuối; BPM là một chế độ hiển thị và nhập liệu, và mọi BPM bạn gõ được đều nằm trong dải riêng của bộ máy thay vì bị cắt lặng lẽ sau lưng bạn.","changelog.5fe2620dd908":"<strong>Điều khiển giao diện</strong> (FT-15) — phông chữ, độ đậm, màu chữ, lề hai bên, giãn dòng, và <strong>vị trí đường dẫn đọc</strong> trên màn hình. Chúng nằm trong bộ máy chứ không ở trạng thái của một cửa sổ, nên bản xem trước, máy chiếu và bản phản chiếu qua mạng nội bộ luôn trông giống nhau.","changelog.ca6865582cd0":"<strong>Đọc to bằng bộ tổng hợp giọng nói của từng hệ thống</strong> (FT-16) — để máy nhắc chữ đọc kịch bản cho bạn nghe theo nhịp bạn đã đặt, để thử thời gian trước khi quay. Phần đánh dấu theo từ đang được đọc, khoảng ngắt thành khoảng lặng thật (<code>--</code> không bao giờ được đọc thành &quot;gạch ngang&quot;), và tua sẽ làm giọng đọc nhảy theo. Nó <strong>chỉ dành cho bản xem trước</strong>: không bao giờ di chuyển máy chiếu của người dẫn. Dùng các giọng có sẵn trong hệ điều hành của bạn (Windows OneCore/SAPI, macOS AVSpeechSynthesis, Linux Speech Dispatcher / espeak-ng) — không kèm bộ máy giọng nói nào.","changelog.cdfbacda0108":"<strong>Giờ mọi ngôn ngữ đều hiển thị, trên mọi máy.</strong> Ứng dụng kèm phông Noto cho cả 18 ngôn ngữ nó hỗ trợ — chữ Latinh, Hy Lạp, Kirin, tiếng Việt, Ả Rập, Devanagari, tiếng Nhật, tiếng Hàn và tiếng Trung giản thể. Chuyển sang tiếng Nhật trên máy chưa cài phông tiếng Nhật từng hiện các ô vuông thay cho giao diện; giờ ứng dụng mang theo thứ nó cần. Chỉ các tập con ký tự mà ngôn ngữ được chọn thực sự dùng mới được nạp, và các phông này cũng hỗ trợ mọi phông đọc, nên chọn &quot;Serif&quot; không bao giờ khiến một ngôn ngữ không đọc được. Các phông theo giấy phép SIL Open Font License; thông báo đi kèm ứng dụng dưới tên <code>THIRD-PARTY.md</code>.","changelog.d1589cdefe34":"<strong>Ứng dụng tự vẽ cửa sổ của mình.</strong> Không có thanh tiêu đề của hệ điều hành: tiêu đề nằm giữa, cùng Cài đặt, Giới thiệu và thu nhỏ / phóng to-khôi phục / đóng ở bên phải — cùng bố cục Freally Player dùng, để các cửa sổ trong bộ ứng dụng trông giống nhau. Thanh này kéo được, nhấp đúp vẫn phóng to, và cửa sổ vẫn đổi kích thước được từ mọi cạnh và góc.","changelog.83b865a057ab":"<strong>Cài đặt giờ là một hộp thoại cài đặt đúng nghĩa</strong>, cùng kiểu với Freally Capture: thanh bên các mục (Chung, Đọc, Giao diện, Máy chiếu, Mạng) có ô tìm kiếm, và chân hộp thoại <strong>OK / Hủy / Áp dụng</strong>. Áp dụng bị vô hiệu cho đến khi có gì đó thực sự thay đổi, và một dấu chấm đánh dấu các mục bạn đã sửa nhưng chưa áp dụng.","changelog.dd1a689ff484":"<strong>Thu nhỏ xuống khay hệ thống</strong> (Cài đặt → Chung). Tắt theo mặc định. Khi bật, thu nhỏ sẽ ẩn cửa sổ và đặt một biểu tượng vào khay; khôi phục sẽ mang cửa sổ trở lại <strong>và gỡ biểu tượng</strong> — ứng dụng hoặc ở thanh tác vụ hoặc ở khay, không bao giờ ở cả hai. Menu khay được dịch như phần còn lại của ứng dụng.","changelog.4124706702a9":"<strong>Biểu tượng ứng dụng giờ là toàn bộ hình vẽ ở mọi kích thước.</strong> <code>0.100.0</code> từng dùng chữ &quot;F&quot; cắt riêng, chỉ có glyph, cho biểu tượng từ 48 px trở xuống, vì chữ thương hiệu trong hình không đọc được ở cỡ nhỏ như vậy. Hóa ra một dấu hiệu nhất quán quan trọng hơn một dấu hiệu dễ đọc nhưng khác, nên việc cắt đã bị bỏ — thanh tác vụ, khay và favicon giờ đều hiện cùng một biểu tượng.","changelog.c347bd2b4305":"Được phát hiện trong đợt rà soát giai đoạn này, trước khi phát hành:","changelog.47424533ef57":"<strong>Chip khoảng dừng có thể xuất hiện ở nơi máy nhắc chữ không dừng.</strong> Trình soạn thảo và chế độ đọc to mỗi bên giữ một bản sao ngữ pháp <code> -- </code> riêng, thiếu các giới hạn mà bộ máy cuộn áp dụng — nên <code>--2.5.3</code> được vẽ thành một khoảng dừng mà máy nhắc chữ sẽ lướt thẳng qua. Cả ba giờ dùng chung một bộ quét.","changelog.b434155bb7d9":"<strong>Nhấp chuột phải vào biểu tượng khay từng khôi phục cửa sổ</strong> thay vì mở menu, khiến mục &quot;Thoát&quot; của chính khay không bấm được.","changelog.ec0cf2fce1a1":"<strong>Các nút của thỏa thuận lần chạy đầu có thể nằm dưới mép dưới cửa sổ</strong> kể từ khi ứng dụng tự vẽ thanh tiêu đề.","changelog.9d5731455d75":"<strong>Cài đặt có thể hiển thị một giá trị mà ứng dụng không dùng.</strong> Một con số bị phía sau giới hạn (ví dụ cổng dưới 1024) vẫn hiển thị như lúc được gõ cho đến lần khởi động lại; giờ hộp thoại hiển thị đúng giá trị thực sự được lưu.","changelog.db89654f4e78":"<strong>Tìm trong Cài đặt có thể để lại sai ngăn trên màn hình</strong>, không có mục nào được làm nổi để giải thích.","changelog.39ed54f3671f":"<strong>Dừng giờ là một thao tác duy nhất trong bộ máy</strong> thay vì một cặp tạm dừng-và-tua lùi do mỗi nút tự ghép, nên mọi thứ khác làm dừng việc cuộn đều hoạt động như nhau.","changelog.e806a291cfc3":"Kiểm thử","changelog.b6521470f6ed":"<strong>Playwright giờ bao quát mọi tính năng Giai đoạn 1 mà nó chạm tới được</strong> — toàn bộ vòng đời thư viện kịch bản, hành vi của chip, bộ chọn màn hình, điều khiển phát, quy đổi BPM, chuỗi xử lý giao diện, và cam kết rằng đọc to không bao giờ chạm vào trạng thái cuộn dùng chung. Cầu nối giả ghi lại các lệnh gọi IPC, nên các bài kiểm thử khẳng định đúng điều giao diện đã yêu cầu phía sau làm.","changelog.965a9f5ce8e2":"<strong>Ứng dụng giờ được khởi chạy và chụp ảnh trên Windows, macOS và Linux ở mỗi lượt CI</strong> (<code>scripts/app-screenshot.mjs</code>), và thất bại nếu nó sập khi khởi động hoặc không vẽ gì. Một lần biên dịch thành công và một webview hiển thị được là hai chuyện khác nhau.","changelog.33678f48d52f":"<strong>Mọi ngôn ngữ được kiểm tra khả năng đọc, không chỉ chuỗi văn bản.</strong> Một bài kiểm thử chuyển ứng dụng sang từng ngôn ngữ trong 18 ngôn ngữ và chứng minh mọi ký tự trong giao diện đều được một phông đi kèm hỗ trợ. Một hệ chữ bị thiếu sẽ hiện thành ô vuông, thứ mà ảnh chụp màn hình và mọi kiểm tra khác đều coi là chữ bình thường — nên tiếng Ả Rập, tiếng Hindi, tiếng Nhật, tiếng Hàn và tiếng Trung đều có thể hỏng lặng lẽ, và chỉ với những người đọc chúng.","changelog.503e7e57035d":"<strong>Một bản dịch lặng lẽ quay về tiếng Anh giờ sẽ làm hỏng bản dựng.</strong> Các đợt dịch hàng loạt để lại tiếng Anh ở mọi chỗ chúng không dịch được, và kết quả vẫn phân tích được và được phát hành trông như đã xong. Các ngoại lệ thật sự — &quot;OK&quot;, &quot;Port&quot;, tên riêng — được liệt kê kèm lý do.","changelog.8b79c1c1b492":"<strong>Việc hiển thị trên Linux giờ được chứng minh, không còn là giả định.</strong> Ảnh chụp màn hình CI chạy trong một container có bộ kết xuất phần mềm, vì máy chạy Linux trơn của GitHub không có GL hoạt động và tạo ra một cửa sổ trống dù ứng dụng có khỏe hay không — một phép kiểm tra không thể thất bại thì chẳng cho chúng ta biết gì.","changelog.bf256044a419":"Mọi thứ thực sự không tự động hóa được — màn hình thứ hai, kính nhắc chữ, giọng đọc nghe được, một chiếc điện thoại trên Wi-Fi của bạn — giờ đều có <strong>bài thực hành từng bước</strong> trong <code>Live-To-Do-List.md</code>.","changelog.8a7525b1492f":"Ghi chú","changelog.f38acbd9b28b":"<strong>Vẫn không AI, không tài khoản, không đo lường từ xa.</strong> Phản chiếu qua mạng nội bộ phục vụ kịch bản của bạn tới các thiết bị bạn trỏ tới, trong mạng của bạn; không gì được tải lên hay chuyển tiếp. Yêu cầu ra ngoài duy nhất của ứng dụng vẫn là kiểm tra cập nhật.","changelog.aadc02e8de62":"<span class=\"release__meta\"><span class=\"release__ver\">v0.100.0</span></span><span class=\"release__title\">21 tháng 7 năm 2026</span>","changelog.7bfe7961d71b":"Giai đoạn dựng khung: ứng dụng giờ đã biên dịch, chạy và yêu cầu chấp nhận thỏa thuận, với bộ máy cuộn dựa trên ký tự được chuyển sang từ Freally Capture.","changelog.19bd3024e088":"<strong>Khung Tauri v2</strong> (FT-00) — một workspace Rust (<code>src-tauri</code>) cùng giao diện React/TypeScript (<code>ui</code>), dùng chung cách tổ chức công cụ với Freally Capture: <code>ci.yml</code>, <code>scripts/ci-local.mjs</code>, <code>deny.toml</code>, và một <code>rust-toolchain.toml</code> cố định, để <code>npm run ci:local</code> chạy toàn bộ kiểm tra ngay từ ngày đầu.","changelog.045988032f64":"<strong>Bộ biểu tượng</strong> (FT-01) — tạo từ hình gốc bằng <code>scripts/make-icons.py</code>, cho Windows, macOS và Linux cùng favicon cho website. Các kích thước từ 48 px trở xuống dùng biến thể <strong>chỉ có glyph &quot;F&quot;</strong>, vì chữ thương hiệu in sẵn trong hình không đọc được dưới 64 px (đã đo, không phải đoán).","changelog.e0471332722d":"<strong>Bộ máy nhắc chữ dựa trên ký tự</strong> (FT-02) — <code>teleprompter.rs</code> và bản song sinh TypeScript <code>ui/src/lib/caesura.ts</code>, chuyển sang từ Freally Capture: vị trí cuộn theo ký tự hiển thị, khoảng ngắt <code> -- </code> trong dòng (<code> --2 </code> cho thời gian dừng tùy chỉnh), điều khiển tua/bước/tốc độ, và đếm ngược trước khi bắt đầu. Bản xem trước và máy chiếu đặt chữ trên cùng một sân khấu cố định chiều rộng rồi co giãn bằng CSS, nên ngắt dòng ở cùng một cột.","changelog.a1b0c9f8ea89":"<strong>Vỏ ứng dụng một cửa sổ</strong> (FT-03) — thanh công cụ, ô nhập kịch bản và bề mặt nhắc chữ trực tiếp, với <strong>Cài đặt</strong> theo mô hình bản nháp/áp dụng (không gì có hiệu lực cho đến khi Áp dụng; Hủy khôi phục đúng những gì bạn đã có) và nền tảng đa ngôn ngữ Fluent cho <strong>18 ngôn ngữ</strong>.","changelog.b45c55ac02ea":"<strong>Trang tài liệu + nhật ký thay đổi</strong> (FT-04) — trang được phục vụ bằng GitHub Pages từ <code>/docs</code>, giống các ứng dụng Freally khác.","changelog.8b96bdf6151d":"<strong>Cổng EULA ở lần chạy đầu</strong> (FT-05) — không thể dùng ứng dụng cho đến khi thỏa thuận được chấp nhận. Việc chấp nhận có phiên bản và <strong>được giữ qua mọi lần lưu cài đặt</strong> (một lỗi từng lọt vào bản phát hành của Freally Capture; giờ có kiểm thử hồi quy cho nó).","changelog.d5361112a7c1":"<strong>Trình báo cáo sự cố và kiểm tra cập nhật</strong> — trình báo sự cố chuẩn của Havoc (báo cáo cục bộ đã làm sạch, thông báo gốc &quot;đã dừng đột ngột&quot;, khởi động lại, và gửi qua GitHub/Gmail/email do chính bạn kích hoạt) cùng việc kiểm tra cập nhật khi khởi động, cho thấy phiên bản và ghi chú phát hành thật trước khi làm bất cứ điều gì.","changelog.198e4f9204b8":"<strong>Không AI, không tài khoản, không đo lường từ xa.</strong> Yêu cầu ra ngoài duy nhất là kiểm tra cập nhật; nó không gửi gì về bạn, máy của bạn hay kịch bản của bạn.","changelog.04d59a3b7905":"Các liên kết tải xuống trên trang chỉ là giữ chỗ cho đến khi quy trình phát hành sẵn sàng.","changelog.a3c71b90162b":"Hạn chế đã biết","changelog.4d18eba61c3f":"<strong>Chưa có bộ cài.</strong> <code>0.100.0</code> là một cột mốc mã nguồn; quy trình phát hành có chữ ký cho từng hệ điều hành là một giai đoạn sau.","changelog.57871c6e9623":"<strong>Cập nhật tự động chưa hoạt động.</strong> Bộ cập nhật được phát hành mà không có khóa công khai để ký, nên nó từ chối mọi gói thay vì cài một gói chưa xác minh — nó thất bại an toàn, nhưng cũng không thể thành công. &quot;Kiểm tra bản cập nhật&quot; sẽ báo lỗi cho đến khi có ký mã."};
